/* Spanish translation of the ISC2 Certified in Cybersecurity practice questions. Options keep the same order as the English bank. */
CertHub.addQuestionsEs("isc2-cc", {
  "ic1": ["Un hospital debe asegurar que los expedientes de los pacientes no se modifiquen sin autorización. ¿Qué principio de seguridad es la preocupación principal?", ["Confidencialidad", "Disponibilidad", "Integridad", "No repudio"], "La integridad protege los datos contra modificaciones no autorizadas o accidentales.", ["La confidencialidad consiste en evitar que personas no autorizadas vean los expedientes, no en impedir que se modifiquen.", "La disponibilidad garantiza que los expedientes se puedan consultar cuando se necesiten; no impide modificaciones no autorizadas.", null, "El no repudio demuestra quién realizó una acción para que no pueda negarlo; por sí solo no impide que se alteren los expedientes."]],
  "ic2": ["En AAA, ¿qué proporciona el accounting (contabilización)?", ["Un registro de lo que hizo un usuario para poder rastrear sus acciones", "La prueba de quién es el usuario", "Una decisión sobre a qué puede acceder el usuario", "El cifrado de la sesión del usuario"], "El accounting registra la actividad del usuario para auditoría y rastreo; la autenticación prueba la identidad y la autorización concede el acceso.", [null, "Probar quién es el usuario corresponde a la autenticación, el paso previo a que se registre cualquier actividad.", "Decidir a qué puede acceder un usuario es autorización, no el registro de lo que realmente hizo.", "Cifrar la sesión protege la confidencialidad en tránsito y no es una de las funciones de AAA."]],
  "ic3": ["Una empresa contrata un seguro cibernético para cubrir las pérdidas de una filtración de datos. ¿Qué tratamiento del riesgo es este?", ["Evitación", "Mitigación", "Aceptación", "Transferencia"], "El seguro traslada el impacto financiero del riesgo a un tercero, lo cual es transferencia.", ["Evitar significa detener por completo la actividad riesgosa; al contratar un seguro la actividad continúa y solo se traslada la pérdida financiera.", "La mitigación aplica controles para reducir la probabilidad o el impacto; el seguro no hace que una filtración sea menos probable ni menos dañina, solo la paga.", "La aceptación significa asumir conscientemente el riesgo uno mismo, mientras que el seguro traslada el costo a la aseguradora.", null]],
  "ic4": ["¿Cuál de los siguientes es un control administrativo (de gestión)?", ["Firewall", "Política de uso aceptable", "Cerradura de puerta", "Cifrado de disco"], "Las políticas son controles administrativos; los firewalls y el cifrado son técnicos, y las cerraduras son físicas.", ["Un firewall es un control técnico (lógico) que filtra tráfico, no una regla o proceso de nivel gerencial.", null, "Una cerradura de puerta es un control físico que restringe el acceso a un espacio.", "El cifrado de disco es un control técnico implementado en software o hardware, no una política administrativa."]],
  "ic5": ["Un miembro de ISC2 se entera de que un colega afirma falsamente tener la certificación CC. ¿Cuál es la MEJOR acción?", ["Ignorarlo porque no es asunto suyo", "Reportarlo mediante el proceso de denuncias éticas de ISC2", "Publicar el nombre del colega en redes sociales", "Pedirle al colega que comparta sus preguntas del examen"], "El Código de Ética exige actuar con honorabilidad y hacer avanzar la profesión, lo que incluye reportar las falsedades por los canales adecuados.", ["El Código de Ética de ISC2 espera que los miembros protejan la profesión, así que ignorar una falsificación conocida de una credencial no es aceptable.", null, "Exponer públicamente a alguien en internet no es un canal adecuado y podría ser en sí mismo poco profesional o difamatorio.", "Pedir preguntas del examen violaría el acuerdo de confidencialidad del examen y no resuelve la afirmación falsa."]],
  "ic6": ["¿Qué término describe la combinación de la probabilidad de que una amenaza explote una debilidad y el impacto si lo hace?", ["Vulnerabilidad", "Amenaza", "Activo", "Riesgo"], "El riesgo se mide por probabilidad e impacto.", ["Una vulnerabilidad es solo la debilidad en sí; no combina probabilidad e impacto.", "Una amenaza es la causa potencial de daño (como un atacante); es un insumo del riesgo, no la combinación descrita.", "Un activo es lo que tiene valor y se protege, no una medida de probabilidad e impacto.", null]],
  "ic7": ["Un usuario inicia sesión con una contraseña y un escaneo de huella dactilar. ¿Qué tipos de factores se usan?", ["Algo que sabes y algo que eres", "Algo que tienes y algo que eres", "Dos factores de conocimiento", "Algo que sabes y algún lugar donde estás"], "Una contraseña es conocimiento y una huella dactilar es un factor biométrico (de inherencia).", [null, "Una contraseña no es algo que tienes; los factores de posesión son objetos como una tarjeta inteligente, un token o un teléfono.", "Una huella dactilar es un factor biométrico (de inherencia), así que solo uno de los dos es un factor de conocimiento.", "Una huella dactilar no es un factor de ubicación; algún lugar donde estás sería algo como la ubicación por GPS o por IP."]],
  "ic8": ["Un servidor web sin parches que un atacante podría explotar es un ejemplo de:", ["Amenaza", "Riesgo", "Vulnerabilidad", "Control"], "Una vulnerabilidad es una debilidad que una amenaza podría explotar.", ["La amenaza sería el atacante o el evento que podría explotar el servidor; el servidor sin parches es en sí la debilidad.", "El riesgo es la probabilidad y el impacto de que se explote la debilidad, no la debilidad en sí.", null, "Un control es una salvaguarda que reduce el riesgo, como aplicar el parche; un servidor sin parches es lo contrario."]],
  "ic9": ["El personal de seguridad revisa grabaciones de cámaras para averiguar quién entró a una sala de servidores fuera de horario. ¿Qué tipo de control está cumpliendo la cámara?", ["Preventivo", "Disuasivo", "Detectivo", "Correctivo"], "Revisar grabaciones para identificar lo ocurrido es una función detectiva.", ["Un control preventivo detiene un evento antes de que ocurra; revisar grabaciones después de los hechos no impide que nadie entre.", "Las cámaras visibles pueden disuadir, pero en este escenario las grabaciones se revisan para identificar quién entró, lo cual es detección.", null, "Un control correctivo arregla o restaura algo después de un incidente; identificar a la persona no corrige nada."]],
  "ic10": ["¿Qué tecnología proporciona MEJOR el no repudio para un correo electrónico?", ["Firma digital", "Cifrado simétrico", "Hash sin clave", "Balanceo de carga"], "Una firma digital creada con la clave privada del remitente prueba quién envió el mensaje, de modo que el remitente no puede negarlo de forma creíble.", [null, "El cifrado simétrico usa una clave compartida, así que cualquiera de las partes pudo haber producido el mensaje y ninguna puede probar quién lo envió.", "Un hash sin clave muestra si los datos cambiaron, pero cualquiera puede calcularlo, así que no vincula el mensaje con un remitente.", "El balanceo de carga distribuye el tráfico para la disponibilidad y no tiene nada que ver con probar quién envió un correo."]],
  "ic11": ["¿Qué documento expresa la intención de seguridad de alto nivel de la dirección y es obligatorio?", ["Guía", "Procedimiento", "Línea base", "Política"], "Una política es la declaración de intención obligatoria de alto nivel; los demás documentos la respaldan.", ["Las guías son consejos recomendados y opcionales, no declaraciones obligatorias de la intención de la dirección.", "Los procedimientos son instrucciones detalladas paso a paso que ejecutan una política, no la declaración de alto nivel en sí.", "Una línea base define una configuración de seguridad mínima; es un documento de apoyo de nivel técnico, no la intención general de la dirección.", null]],
  "ic12": ["Una empresa debe proteger los datos personales porque el gobierno lo exige por ley. ¿Cuál es el origen de este requisito?", ["Una guía interna", "Legislación o regulación", "Una buena práctica de la industria", "Una recomendación de un proveedor"], "Los requisitos impuestos por el gobierno, como el GDPR, provienen de leyes y regulaciones y no son opcionales.", ["Una guía interna la redacta la propia empresa y suele ser opcional, no impuesta por el gobierno.", null, "Las buenas prácticas de la industria son recomendaciones voluntarias, no requisitos legales del gobierno.", "Una recomendación de un proveedor es un consejo de un suministrador y no tiene fuerza legal."]],
  "ic13": ["Un atacante introduce registros manipulados en los datos usados para entrenar el modelo de IA de una empresa. ¿Qué principio se ve amenazado principalmente?", ["Disponibilidad", "Integridad", "Accounting (contabilización)", "No repudio"], "El envenenamiento de datos corrompe los datos de entrenamiento, lo que ataca su integridad y la confiabilidad de los resultados del modelo.", ["Los datos de entrenamiento envenenados normalmente no hacen que el modelo sea inaccesible; el problema es que sus resultados dejan de ser confiables.", null, "El accounting es el registro de las acciones de los usuarios en AAA, no una propiedad de los datos de entrenamiento que el envenenamiento corrompe.", "El no repudio consiste en probar quién realizó una acción; introducir registros falsos ataca en cambio la exactitud de los datos."]],
  "ic14": ["¿Qué enfoque usa una evaluación de riesgos cualitativa?", ["Valores monetarios exactos como la expectativa de pérdida anualizada", "Solo los costos históricos de filtraciones", "Valores hash de archivos críticos", "Calificaciones como alto, medio y bajo"], "La evaluación cualitativa clasifica los riesgos con calificaciones descriptivas; la evaluación cuantitativa usa valores monetarios.", ["Los valores monetarios exactos como la ALE se usan en la evaluación de riesgos cuantitativa, no en la cualitativa.", "Basarse solo en los costos históricos de filtraciones sigue siendo un enfoque monetario basado en datos y no es la forma en que la evaluación cualitativa califica el riesgo.", "Los hashes de archivos son verificaciones de integridad, no una forma de calificar la probabilidad o el impacto del riesgo.", null]],
  "ic15": ["¿Qué medida está diseñada para advertir con anticipación a la dirección que la exposición al riesgo está aumentando?", ["Indicador clave de riesgo (KRI)", "Objetivo de punto de recuperación", "Acuerdo de nivel de servicio", "Tiempo medio de reparación"], "Los KRI son métricas elegidas específicamente para señalar un riesgo creciente antes de que se convierta en un incidente.", [null, "Un objetivo de punto de recuperación define la pérdida de datos aceptable para la planificación de la recuperación; no es una métrica de alerta temprana de riesgo creciente.", "Un acuerdo de nivel de servicio fija metas de servicio acordadas con un proveedor; no señala una exposición al riesgo creciente.", "El tiempo medio de reparación mide qué tan rápido se corrigen las fallas después de que ocurren, no si el riesgo tiende a aumentar."]],
  "ic16": ["¿Cuál es el propósito principal de la gobernanza de seguridad?", ["Ajustar las reglas del firewall a diario", "Hacer que los usuarios elijan contraseñas robustas", "Asegurar que las actividades de seguridad se alineen con los objetivos del negocio bajo la supervisión de la dirección", "Ejecutar respaldos nocturnos"], "La gobernanza establece la dirección, la rendición de cuentas y la supervisión para que la seguridad respalde los objetivos del negocio.", ["Ajustar el firewall a diario es una tarea operativa, no la supervisión y dirección de la alta gerencia que proporciona la gobernanza.", "Exigir contraseñas robustas es un control técnico o administrativo específico, no el propósito de la gobernanza en su conjunto.", null, "Ejecutar respaldos nocturnos es una actividad operativa que la gobernanza puede exigir, pero no es la gobernanza en sí."]],
  "ic17": ["¿Qué describe el apetito de riesgo de una organización?", ["La cantidad de vulnerabilidades encontradas en los escaneos", "El costo de un control de seguridad", "La cantidad de riesgo que está dispuesta a aceptar para lograr sus objetivos", "El valor total de sus activos"], "El apetito de riesgo es el nivel de riesgo que la dirección está dispuesta a aceptar.", ["La cantidad de hallazgos de escaneo mide las vulnerabilidades presentes, no cuánto riesgo está dispuesta a aceptar la dirección.", "El costo de un control es un insumo para las decisiones de tratamiento del riesgo, no una declaración del apetito de riesgo.", null, "El valor total de los activos ayuda a dimensionar el impacto potencial, pero no expresa la disposición de la organización a asumir riesgos."]],
  "ic18": ["¿Qué enfoque es el MÁS eficaz para construir una cultura de seguridad sólida?", ["Capacitación de concientización continua respaldada por el apoyo visible de la dirección", "Una presentación única durante la inducción", "Exponer públicamente a los empleados que hacen clic en enlaces de phishing", "Enviar la política por correo una vez al año"], "La cultura crece con capacitación continua y relevante y con líderes que dan el ejemplo; exponer públicamente a las personas desalienta el reporte.", [null, "Una presentación única en la inducción se olvida rápido y no sostiene los comportamientos que conforman una cultura de seguridad.", "La exposición pública desalienta a los empleados a reportar errores, lo que debilita la cultura en lugar de fortalecerla.", "Enviar la política por correo una vez al año es pasivo e infrecuente, por lo que rara vez cambia el comportamiento cotidiano."]],
  "ic19": ["En GRC, ¿qué significa cumplimiento (compliance)?", ["Comprar las herramientas de seguridad más nuevas", "No tener nunca un incidente", "Contratar a un director de seguridad de la información (CISO)", "Cumplir los requisitos de las leyes, regulaciones, estándares y contratos aplicables"], "El cumplimiento es la conformidad con requisitos externos e internos, como PCI DSS o HIPAA.", ["Comprar herramientas nuevas no demuestra por sí solo conformidad con ninguna ley, estándar o contrato.", "El cumplimiento no garantiza cero incidentes; una organización que cumple plenamente todavía puede sufrir una filtración.", "Contratar a un CISO puede apoyar un programa de seguridad, pero el cumplimiento consiste en satisfacer requisitos, no en cubrir un puesto.", null]],
  "ic20": ["La tasa de clics en correos de phishing simulados baja del 20% al 5% en un año. ¿Qué muestra principalmente esta métrica?", ["La disponibilidad del servidor de correo", "La eficacia del programa de concientización de seguridad", "La robustez del cifrado", "El cumplimiento de parches"], "Los resultados de las simulaciones de phishing son una medida común de qué tan bien la capacitación de concientización está cambiando el comportamiento.", ["La disponibilidad del servidor de correo se mediría por el tiempo de actividad, no por cuántos usuarios hacen clic en enlaces de phishing simulados.", null, "Las tasas de clics en phishing reflejan el comportamiento de los usuarios y no dicen nada sobre la robustez de los algoritmos de cifrado.", "El cumplimiento de parches mide cuántos sistemas tienen actualizaciones al día, lo cual no tiene relación con que los usuarios hagan clic en correos de phishing."]],
  "ic21": ["¿Quién es el responsable final de aceptar el riesgo en una organización?", ["La mesa de ayuda", "La alta dirección y la junta directiva", "Los usuarios finales individuales", "El auditor externo"], "La alta dirección es dueña de las decisiones de riesgo; los equipos de seguridad asesoran y los auditores evalúan.", ["La mesa de ayuda brinda soporte a los usuarios y sigue la política; no tiene autoridad para aceptar riesgos de la organización.", null, "Los usuarios finales deben seguir la política, pero no son responsables de las decisiones de riesgo de toda la organización.", "Los auditores externos evalúan los controles de forma independiente y deben mantener esa independencia, así que no aceptan riesgos en nombre de la organización."]],
  "ic22": ["¿Qué documento de gobernanza da instrucciones paso a paso para completar una tarea?", ["Política", "Guía", "Línea base", "Procedimiento"], "Los procedimientos son instrucciones detalladas paso a paso que implementan políticas y estándares.", ["Una política es una declaración de intención de alto nivel y no da instrucciones paso a paso.", "Una guía ofrece recomendaciones opcionales en lugar de pasos detallados y obligatorios.", "Una línea base especifica un estándar mínimo de configuración, no la secuencia de pasos para completar una tarea.", null]],
  "ic23": ["Un gerente de seguridad prepara un informe para los ejecutivos. ¿En qué debe enfocarse?", ["Riesgos y métricas del programa resumidos en términos de negocio", "Cada entrada de log sin procesar del SIEM", "La lista completa de reglas del firewall", "El código fuente de las aplicaciones"], "Los informes para ejecutivos deben traducir el estado de la seguridad en riesgo de negocio para que los líderes puedan decidir.", [null, "Las entradas de log sin procesar del SIEM son demasiado detalladas para los ejecutivos y no se traducen en un riesgo de negocio sobre el que puedan actuar.", "Una lista completa de reglas del firewall es detalle técnico para ingenieros, no un resumen que los ejecutivos puedan usar para tomar decisiones.", "El código fuente de las aplicaciones es irrelevante para una audiencia ejecutiva y no dice nada sobre la postura de riesgo general."]],
  "ic24": ["Un nuevo proveedor procesará los datos de clientes de la empresa. ¿Qué debe ocurrir antes de firmar el contrato?", ["Darle al proveedor acceso completo de administrador", "Omitir la revisión porque el proveedor es barato", "Evaluar la seguridad del proveedor e incluir requisitos de seguridad en el contrato", "Esperar a que ocurra un incidente para revisar al proveedor"], "La gestión de riesgos de terceros evalúa a los proveedores desde el inicio y plasma en el contrato los términos de seguridad y de notificación.", ["Otorgar acceso completo de administrador antes de cualquier evaluación viola el mínimo privilegio y expone a la empresa a riesgos no evaluados.", "Un costo bajo no reduce el riesgo de manejar datos de clientes; el proveedor igual necesita una revisión de seguridad.", null, "Esperar un incidente es reactivo; para entonces ya no se pueden negociar de antemano los términos contractuales ni los requisitos de seguridad."]],
  "ic25": ["¿Qué afirmación describe MEJOR el mínimo privilegio?", ["Todo el personal de TI recibe derechos de administrador", "Todos reciben el mismo acceso por simplicidad", "Los usuarios reciben solo el acceso que necesitan para hacer su trabajo", "El acceso se otorga según la antigüedad"], "El mínimo privilegio limita a cada usuario al acceso mínimo que requiere su trabajo.", ["Dar derechos de administrador a todo el personal de TI otorga mucho más acceso del que necesita la mayoría de los roles, lo opuesto al mínimo privilegio.", "Dar a todos el mismo acceso ignora las necesidades de cada puesto y otorga privilegios excesivos a la mayoría de los usuarios.", null, "La antigüedad no determina la necesidad; el personal de mayor rango a menudo requiere menos acceso a los sistemas que los especialistas."]],
  "ic26": ["¿Cuál es un ejemplo de separación de funciones?", ["Un empleado crea los pagos a proveedores y otro empleado distinto los aprueba", "Un administrador tiene todas las contraseñas", "Los miembros del equipo comparten un mismo inicio de sesión", "Un gerente aprueba su propio informe de gastos"], "Dividir una tarea sensible entre varias personas impide que una sola cometa un fraude y lo oculte.", [null, "Que un administrador tenga todas las contraseñas concentra el control en una sola persona en lugar de dividirlo.", "Un inicio de sesión compartido destruye la rendición de cuentas individual y no divide ninguna tarea sensible entre personas.", "Que un gerente apruebe su propio informe de gastos es exactamente el conflicto que la separación de funciones busca evitar."]],
  "ic27": ["¿En qué modelo de control de acceso se asignan los permisos a funciones laborales y los usuarios los obtienen al ser asignados a esas funciones?", ["Control de acceso discrecional", "Control de acceso obligatorio", "Control de acceso basado en horarios", "Control de acceso basado en roles"], "RBAC otorga permisos a roles, y los usuarios los heredan por pertenecer al rol.", ["En DAC el dueño del recurso decide quién obtiene acceso, en lugar de que los permisos provengan de funciones laborales.", "MAC otorga el acceso comparando etiquetas impuestas por el sistema con las autorizaciones de seguridad, no por pertenencia a un rol.", "El control de acceso basado en horarios restringe cuándo se permite el acceso; no asigna permisos a funciones laborales.", null]],
  "ic28": ["Un sistema militar otorga acceso comparando las etiquetas de clasificación de los datos con las autorizaciones de seguridad (clearances) de los usuarios. ¿Qué modelo es este?", ["Control de acceso discrecional", "Control de acceso obligatorio", "Control de acceso basado en roles", "Control de acceso basado en reglas"], "MAC lo impone el sistema usando etiquetas y autorizaciones de seguridad, no los dueños de los datos.", ["En DAC el dueño de los datos elige quién tiene acceso, mientras que aquí el sistema impone etiquetas y autorizaciones.", null, "RBAC asigna permisos según el rol laboral, no comparando etiquetas de clasificación con autorizaciones de seguridad.", "El control de acceso basado en reglas aplica reglas definidas por el administrador (como las ACL de un firewall), no etiquetas de clasificación comparadas con autorizaciones."]],
  "ic29": ["Un usuario comparte una carpeta y elige qué compañeros pueden abrirla. ¿Qué modelo es este?", ["Control de acceso obligatorio", "Control de acceso discrecional", "Control de acceso basado en roles", "Etiquetas de atributos asignadas por el sistema"], "En DAC el dueño de un recurso decide quién puede acceder a él.", ["En MAC el sistema impone el acceso según etiquetas, y los usuarios no pueden elegir quién abre un recurso.", null, "En RBAC el acceso proviene de roles laborales definidos por los administradores, no de que un dueño elija a compañeros específicos.", "Las etiquetas de atributos asignadas por el sistema describen un enfoque obligatorio o basado en atributos, no a un dueño que elige quién obtiene acceso."]],
  "ic30": ["Un empleado es despedido hoy. ¿Cuál es la acción de identidad MÁS importante?", ["Restablecer su contraseña el próximo trimestre", "Mover la cuenta a otro departamento", "Dejar la cuenta activa para la entrega de pendientes", "Deshabilitar o eliminar su acceso de inmediato"], "La baja oportuna de accesos impide que un exempleado use accesos que ya no debería tener.", ["Esperar hasta el próximo trimestre deja utilizable durante meses el acceso de un empleado despedido.", "Mover la cuenta a otro departamento la mantiene activa y aún utilizable por el exempleado.", "Dejar la cuenta activa para la entrega permite que alguien que ya no trabaja ahí conserve el acceso; la entrega debe hacerse mediante un gerente o recursos compartidos.", null]],
  "ic31": ["¿Qué es la acumulación de privilegios (privilege creep)?", ["Los usuarios siguen acumulando permisos a medida que cambian de rol", "Un atacante descifra una contraseña por fuerza bruta", "Un lector de credenciales falla en modo abierto durante un corte de energía", "Un firewall bloquea tráfico legítimo"], "La acumulación de privilegios ocurre cuando no se retiran los accesos anteriores tras un cambio de rol; las revisiones de acceso la detectan.", [null, "Descifrar una contraseña por fuerza bruta es un ataque a credenciales, no la acumulación gradual de permisos.", "Que un lector de credenciales falle en modo abierto es un comportamiento fail-safe de seguridad física, sin relación con la acumulación de permisos con el tiempo.", "Que un firewall bloquee tráfico legítimo es un falso positivo o un error de configuración, no acumulación de privilegios."]],
  "ic32": ["¿Cuál es el propósito principal de una revisión periódica de accesos?", ["Acelerar el inicio de sesión de los usuarios", "Instalar los parches faltantes", "Confirmar que los usuarios aún necesitan el acceso que tienen", "Restablecer todas las contraseñas"], "Las revisiones de acceso verifican que los permisos actuales sigan siendo apropiados y retiran los que no lo son.", ["Las revisiones de acceso comprueban si los permisos son apropiados; no afectan la velocidad del inicio de sesión.", "Instalar parches es gestión de vulnerabilidades, no una revisión de quién tiene acceso a qué.", null, "Restablecer todas las contraseñas cambia las credenciales, pero no verifica si el acceso de cada usuario sigue siendo necesario."]],
  "ic33": ["Un vestíbulo de control de acceso (mantrap) en la entrada de un centro de datos previene principalmente:", ["El phishing", "La inyección SQL", "El tailgating (colarse detrás de alguien)", "Las infecciones de malware"], "Un vestíbulo deja pasar solo a una persona autenticada a la vez, lo que impide que otros entren siguiendo a alguien.", ["El phishing es un ataque por correo o mensajería, que un vestíbulo de entrada físico no puede detener.", "La inyección SQL es un ataque de capa de aplicación contra bases de datos, sin relación con controlar quién cruza una puerta.", null, "Las infecciones de malware se propagan por software y redes, no por personas que entran a un edificio detrás de alguien."]],
  "ic34": ["Un usuario escribe su nombre de usuario en una pantalla de inicio de sesión. ¿Qué paso es este?", ["Identificación", "Autenticación", "Autorización", "Accounting (contabilización)"], "Declarar una identidad es identificación; probarla con una contraseña u otro factor es autenticación.", [null, "La autenticación consiste en probar la identidad declarada, por ejemplo al ingresar una contraseña, lo cual ocurre después de escribir el nombre de usuario.", "La autorización decide a qué puede acceder el usuario una vez probada su identidad.", "El accounting registra lo que hace el usuario después de obtener acceso, no el acto de declarar una identidad."]],
  "ic35": ["¿Cuál es el beneficio principal del inicio de sesión único (SSO)?", ["Elimina la necesidad de autenticarse", "Garantiza que no haya filtraciones", "Elimina la necesidad de MFA", "Los usuarios se autentican una vez para acceder a varios sistemas"], "SSO permite que una sola autenticación dé acceso a muchas aplicaciones, lo que reduce la fatiga de contraseñas.", ["SSO no elimina la autenticación; el usuario sigue autenticándose, solo que una vez para muchos sistemas.", "Ninguna tecnología garantiza cero filtraciones, y una credencial de SSO comprometida puede de hecho exponer muchos sistemas a la vez.", "SSO no reemplaza a MFA; como un solo inicio de sesión desbloquea muchos sistemas, debe protegerse con MFA.", null]],
  "ic36": ["¿Cuál es la MEJOR práctica para el acceso privilegiado de los administradores de sistemas?", ["Usar la cuenta de administrador para el correo diario", "Usar una cuenta de administrador separada solo para tareas administrativas, protegida con MFA", "Compartir una sola cuenta de administrador en el equipo", "Desactivar el registro (logging) para las cuentas de administrador"], "Las cuentas de administrador separadas y protegidas con MFA limitan la exposición y mantienen las acciones administrativas atribuibles a una persona.", ["Usar una cuenta de administrador para el correo diario expone privilegios muy poderosos al phishing y al malware.", null, "Una cuenta de administrador compartida elimina la rendición de cuentas individual, ya que las acciones no se pueden rastrear hasta una persona.", "Desactivar el registro de las cuentas de administrador oculta las acciones más poderosas a la auditoría y la investigación."]],
  "ic37": ["¿Qué puerto usa HTTPS de forma predeterminada?", ["80", "443", "22", "25"], "HTTPS usa TCP 443; el 80 es HTTP, el 22 es SSH y el 25 es SMTP.", ["El puerto 80 es el predeterminado para HTTP sin cifrar, no para HTTPS.", null, "El puerto 22 lo usa SSH para acceso seguro a una shell remota, no para tráfico web HTTPS.", "El puerto 25 lo usa SMTP para enviar correo, no para tráfico web."]],
  "ic38": ["¿En qué capa del modelo OSI ocurre el enrutamiento IP?", ["Física", "Enlace de datos", "Transporte", "Red"], "El enrutamiento por dirección IP ocurre en la capa 3, la capa de red.", ["La capa física (capa 1) transmite bits sin procesar por el medio y no tiene el concepto de direcciones IP.", "La capa de enlace de datos (capa 2) reenvía tramas usando direcciones MAC dentro de una red local, no enrutamiento IP.", "La capa de transporte (capa 4) gestiona la entrega de extremo a extremo con puertos TCP o UDP, no el enrutamiento entre redes.", null]],
  "ic39": ["¿Qué protocolo debe reemplazar a Telnet para la administración remota segura?", ["SSH en el puerto 22", "FTP en el puerto 21", "HTTP en el puerto 80", "SNMP en el puerto 161"], "SSH cifra la sesión, mientras que Telnet envía todo, incluidas las contraseñas, en texto claro.", [null, "FTP en el puerto 21 transfiere archivos y envía las credenciales en texto claro, así que no es seguro ni ofrece una shell remota.", "HTTP en el puerto 80 es tráfico web sin cifrar y no ofrece administración segura por línea de comandos.", "SNMP en el puerto 161 sirve para monitorear dispositivos de red, y sus versiones antiguas envían las community strings en texto claro."]],
  "ic40": ["Una empresa usa un servicio de correo SaaS. ¿Qué responsabilidad de seguridad sigue siendo de la empresa?", ["La seguridad física del centro de datos", "Aplicar parches a los hipervisores del proveedor", "Gestionar el acceso de los usuarios y los datos que almacena", "Escribir el código de la aplicación"], "Bajo el modelo de responsabilidad compartida, los clientes de SaaS siguen siendo dueños de sus identidades, configuraciones de acceso y datos.", ["En SaaS el proveedor es responsable de la seguridad física del centro de datos, no el cliente.", "El proveedor aplica parches a sus propios hipervisores e infraestructura; en SaaS los clientes no tienen acceso a ellos.", null, "En SaaS el proveedor escribe y mantiene el código de la aplicación; el cliente solo la usa."]],
  "ic41": ["¿A qué principio apunta principalmente un ataque de denegación de servicio distribuida (DDoS)?", ["Confidencialidad", "Integridad", "Disponibilidad", "No repudio"], "Un DDoS inunda un servicio para que los usuarios legítimos no puedan acceder a él.", ["Un DDoS no expone datos a personas no autorizadas, que es lo que protege la confidencialidad.", "Un DDoS inunda un servicio con tráfico, pero normalmente no modifica datos, así que la integridad no es el objetivo principal.", null, "El no repudio se refiere a probar quién realizó una acción, algo que una inundación de tráfico no ataca."]],
  "ic42": ["¿Cuál es la idea central de zero trust?", ["Nunca confiar, siempre verificar cada solicitud de acceso", "Confiar en todos los dispositivos dentro del perímetro", "Permitir el acceso solo a través de una VPN", "Desactivar el registro para mejorar la velocidad"], "Zero trust elimina la confianza implícita basada en la ubicación de red y verifica cada solicitud.", [null, "Confiar en todos los dispositivos dentro del perímetro es el modelo tradicional de castillo y foso que zero trust rechaza.", "Una VPN solo establece una conexión de red y, una vez conectado, aún puede otorgar una confianza implícita amplia; zero trust verifica cada solicitud.", "Desactivar el registro reduce la visibilidad, mientras que zero trust depende del monitoreo y la verificación continuos."]],
  "ic43": ["Una organización coloca sus cámaras inteligentes y otros dispositivos IoT en su propia VLAN. ¿Qué es esto?", ["Balanceo de carga", "Reenvío de puertos", "Traducción de direcciones de red", "Segmentación de red para limitar el movimiento lateral"], "La segmentación aísla los dispositivos menos confiables para que un compromiso no se propague fácilmente.", ["El balanceo de carga reparte el tráfico entre servidores para el rendimiento y la disponibilidad; no aísla dispositivos.", "El reenvío de puertos redirige el tráfico entrante de un puerto a un host interno y no separa grupos de dispositivos.", "NAT traduce direcciones privadas a públicas; no coloca dispositivos en un segmento aislado.", null]],
  "ic44": ["¿Qué puede hacer un sistema de prevención de intrusiones (IPS) que un sistema de detección de intrusiones (IDS) no puede?", ["Registrar tráfico sospechoso", "Bloquear tráfico malicioso en línea (inline)", "Cifrar el tráfico de red", "Asignar direcciones IP"], "Un IPS se ubica en la ruta del tráfico y puede descartar paquetes maliciosos; un IDS solo alerta.", ["Registrar tráfico sospechoso es algo que un IDS ya hace, así que no es la capacidad que distingue al IPS.", null, "Ni un IDS ni un IPS cifran el tráfico; esa es la función de protocolos como TLS o IPsec.", "Asignar direcciones IP es la función de DHCP, no de un sistema de detección o prevención de intrusiones."]],
  "ic45": ["Varios hospitales comparten una nube creada para sus necesidades regulatorias comunes. ¿Qué modelo de implementación es este?", ["Pública", "Comunitaria", "Privada", "Híbrida"], "Una nube comunitaria la comparten organizaciones con intereses comunes, como el cumplimiento normativo.", ["Una nube pública está abierta a cualquier cliente, no creada para un grupo específico con necesidades regulatorias compartidas.", null, "Una nube privada sirve a una sola organización, no a varios hospitales que la comparten.", "Una nube híbrida combina dos o más modelos de implementación, como privada y pública, en lugar de ser compartida por un grupo de organizaciones similares."]],
  "ic46": ["Un empleado trabaja desde el Wi-Fi de una cafetería. ¿Qué protege MEJOR contra ataques de intermediario (man-in-the-middle)?", ["Elegir una red con un nombre más largo", "Desactivar el firewall del equipo", "Desactivar las actualizaciones automáticas", "Usar una VPN u otra conexión cifrada"], "Cifrar el tráfico de extremo a extremo impide que un atacante en la misma red lo lea o lo altere.", ["El nombre de la red no influye en la seguridad, y los atacantes pueden crear fácilmente nombres de red falsos y convincentes.", "Desactivar el firewall del equipo elimina protección y deja a la laptop más expuesta en una red pública.", "Desactivar las actualizaciones automáticas deja vulnerabilidades conocidas sin parchear y no protege el tráfico en tránsito.", null]],
  "ic47": ["¿Qué es una DMZ (subred filtrada o screened subnet)?", ["Un segmento de red para servidores expuestos al público, separado de la red interna", "Un protocolo de cifrado inalámbrico", "Un tipo de malware", "Un sitio alterno de recuperación"], "Una DMZ aloja servicios expuestos a internet mientras los firewalls los mantienen separados de los sistemas internos.", [null, "Los protocolos de cifrado inalámbrico son estándares como WPA2 o WPA3, no segmentos de red para servidores públicos.", "El malware es software malicioso, mientras que una DMZ es un diseño de red usado para la defensa.", "Los sitios alternos de recuperación (sitios hot, warm o cold) son para la continuidad del negocio, no para alojar servidores expuestos al público."]],
  "ic48": ["¿Qué describe la Infraestructura como Servicio (IaaS)?", ["El proveedor gestiona el sistema operativo y la aplicación", "El cliente renta una aplicación terminada", "El cliente renta máquinas virtuales, almacenamiento y red, y gestiona el sistema operativo y las aplicaciones", "El cliente solo renta espacio en rack para su propio hardware"], "En IaaS el proveedor opera la infraestructura física mientras el cliente gestiona todo desde el sistema operativo hacia arriba.", ["Cuando el proveedor gestiona el sistema operativo y la aplicación, se trata de PaaS o SaaS, no de IaaS.", "Rentar una aplicación terminada es SaaS, donde el cliente solo usa el software.", null, "Rentar espacio en rack para tu propio hardware es colocation (coubicación), que no es un modelo de servicio en la nube."]],
  "ic49": ["¿Qué característica de la nube permite que los recursos crezcan y se reduzcan automáticamente según la demanda?", ["Servicio medido", "Amplio acceso a la red", "Elasticidad rápida", "Agrupación de recursos"], "La elasticidad rápida es la capacidad de escalar los recursos rápidamente hacia arriba o hacia abajo.", ["Servicio medido significa que el uso se mide y se factura; no describe el escalado automático.", "Amplio acceso a la red significa que los servicios son accesibles por la red desde muchos tipos de dispositivos, no que escalen según la demanda.", null, "La agrupación de recursos significa que el proveedor comparte recursos entre muchos inquilinos; hace posible la elasticidad, pero no es la capacidad de escalar en sí."]],
  "ic50": ["¿Qué significa defensa en profundidad?", ["Usar múltiples capas de controles para que una falla no exponga los activos", "Depender de un solo firewall robusto", "Usar solo cifrado", "Depender solo de la capacitación de los usuarios"], "Los controles en capas obligan a un atacante a vencer varias defensas, no solo una.", [null, "Depender de un solo firewall es un punto único de falla, lo opuesto a una defensa en capas.", "El cifrado por sí solo es apenas un control; si se roban las claves o fallan los controles de acceso, nada más protege los activos.", "La capacitación de usuarios por sí sola es una sola capa, y las personas seguirán cometiendo errores sin controles técnicos que las respalden."]],
  "ic51": ["¿Qué fase de respuesta a incidentes va primero?", ["Contención", "Erradicación", "Recuperación", "Preparación"], "La preparación (planes, equipo, herramientas, capacitación) ocurre antes de que se detecte cualquier incidente.", ["La contención ocurre solo después de detectar y analizar un incidente, así que no puede ser la primera.", "La erradicación elimina la amenaza después de la contención, mucho después de iniciado el ciclo de vida.", "La recuperación restablece las operaciones normales cerca del final del ciclo de vida, después de la erradicación.", null]],
  "ic52": ["¿Qué algoritmo usarías para comprobar que un archivo descargado no fue alterado?", ["AES", "SHA-256", "RSA", "TLS"], "SHA-256 es una función hash; si los hashes coinciden, el archivo no cambió.", ["AES es un algoritmo de cifrado simétrico para la confidencialidad; no produce una suma de verificación para comprobar la integridad de un archivo.", null, "RSA es un algoritmo asimétrico para cifrado y firmas, no un hash para comparar el contenido de archivos.", "TLS es un protocolo que protege los datos en tránsito; no es un algoritmo para verificar un archivo descargado después de recibirlo."]],
  "ic53": ["¿Por qué las organizaciones envían los logs a un SIEM central?", ["Para que las laptops sean más rápidas", "Para correlacionar eventos entre sistemas y alertar sobre patrones sospechosos", "Para reemplazar los respaldos", "Para cifrar los discos duros"], "Un SIEM agrega y correlaciona logs, lo que hace visibles los ataques que abarcan varios sistemas.", ["Enviar logs a un SIEM no acelera las laptops; el reenvío de logs de hecho consume algunos recursos del endpoint.", null, "Un SIEM almacena y analiza logs; no puede restaurar sistemas ni datos como lo hacen los respaldos.", "El cifrado de disco es un control del endpoint y no es una función de un SIEM."]],
  "ic54": ["¿Qué actividad forma parte del hardening (endurecimiento) de sistemas?", ["Instalar todos los servicios opcionales", "Mantener las contraseñas predeterminadas", "Desactivar el registro", "Eliminar servicios innecesarios, cambiar los valores predeterminados y aplicar parches"], "El hardening reduce la superficie de ataque al eliminar lo que no se necesita y asegurar lo que queda.", ["Instalar todos los servicios opcionales aumenta la superficie de ataque, lo opuesto al hardening.", "Las contraseñas predeterminadas están publicadas ampliamente, así que conservarlas facilita comprometer los sistemas.", "Desactivar el registro elimina la visibilidad de los ataques y no forma parte del hardening.", null]],
  "ic55": ["¿Qué define un objetivo de punto de recuperación (RPO)?", ["La pérdida máxima aceptable de datos, medida en tiempo", "El tiempo de inactividad máximo aceptable", "El costo total de la recuperación", "La cantidad de copias de respaldo que se conservan"], "El RPO fija cuántos datos, medidos en tiempo, se pueden perder; el RTO fija cuánto tiempo pueden estar caídos los sistemas.", [null, "El tiempo de inactividad máximo aceptable lo describe el objetivo de tiempo de recuperación (RTO), no el RPO.", "El costo de la recuperación es una consideración presupuestaria, no lo que mide el RPO.", "La cantidad de copias de respaldo es un detalle de la política de respaldos; el RPO define cuánta pérdida de datos, medida en tiempo, es aceptable."]],
  "ic56": ["Un equipo contuvo un ransomware, lo eliminó y restauró los sistemas. ¿Qué debe hacer a continuación?", ["Detección", "Preparación", "Realizar una revisión de lecciones aprendidas", "Identificación"], "La actividad posterior al incidente recoge lo que salió bien y lo que hay que mejorar, y cierra el ciclo de vida.", ["La detección ocurre al inicio del manejo de un incidente, no después de que los sistemas ya fueron restaurados.", "La preparación es la fase inicial antes de que ocurran incidentes; el equipo primero debe recoger las lecciones que luego la retroalimentarán.", null, "La identificación del incidente ya ocurrió antes de la contención, así que no es el siguiente paso después de la recuperación."]],
  "ic57": ["¿Qué determina principalmente una etiqueta de clasificación de datos?", ["Qué proveedor de hardware comprar", "El límite de tamaño de archivo", "Cómo deben manejarse los datos, por ejemplo el cifrado y quién puede acceder a ellos", "Qué marca de respaldo usar"], "La clasificación define las reglas de manejo para la protección, el acceso, la retención y la destrucción.", ["Las etiquetas de clasificación describen la sensibilidad de los datos, no qué proveedor de hardware comprar.", "La clasificación no fija límites de tamaño de archivo; define cómo deben protegerse y manejarse los datos.", null, "Elegir una marca de respaldo es una decisión de compras; la clasificación puede influir en los requisitos de respaldo, pero no en la marca."]],
  "ic58": ["Una empresa va a desechar laptops con SSD que contenían datos sensibles. ¿Cuál es el MEJOR método?", ["Destrucción física o borrado criptográfico", "Eliminar los archivos", "Un formateo rápido", "Cambiar el nombre de las carpetas"], "Eliminar o formatear deja datos recuperables; la destrucción o el borrado criptográfico los hace irrecuperables.", [null, "Eliminar archivos solo quita las referencias a los datos, que a menudo todavía se pueden recuperar con herramientas forenses.", "Un formateo rápido reescribe las estructuras del sistema de archivos, pero deja recuperable la mayor parte de los datos subyacentes.", "Cambiar el nombre de las carpetas solo modifica etiquetas y deja intactos todos los datos sensibles."]],
  "ic59": ["Alice quiere enviarle a Bob un mensaje confidencial usando cifrado asimétrico. ¿Con qué clave cifra ella?", ["La clave privada de Alice", "La clave pública de Alice", "La clave privada de Bob", "La clave pública de Bob"], "Cifrar con la clave pública de Bob significa que solo la clave privada de Bob puede descifrarlo.", ["Cifrar con la clave privada de Alice permite que cualquiera con su clave pública lo descifre, lo cual prueba el origen pero no brinda confidencialidad.", "Todo lo cifrado con la clave pública de Alice solo se puede descifrar con la clave privada de Alice, así que Bob no podría leerlo.", "Alice nunca debería tener la clave privada de Bob; solo Bob la posee, y se usa para descifrar el mensaje, no para cifrarlo.", null]],
  "ic60": ["¿Cuál es el propósito de un plan de continuidad del negocio?", ["Restaurar solo los sistemas de TI", "Mantener funcionando las funciones críticas del negocio durante y después de una interrupción", "Sancionar al personal después de los incidentes", "Reemplazar el plan de respuesta a incidentes"], "El BCP mantiene en marcha las operaciones esenciales; la recuperación ante desastres se enfoca en restaurar TI.", ["Restaurar los sistemas de TI es el enfoque de la recuperación ante desastres, que es solo una parte de mantener funcionando todo el negocio.", null, "Sancionar al personal es un asunto de Recursos Humanos y no es el propósito de la planificación de continuidad.", "Un BCP complementa el plan de respuesta a incidentes en lugar de reemplazarlo; cada uno cubre un alcance distinto."]],
  "x1": ["Una empresa coloca letreros en su entrada advirtiendo que los intrusos serán procesados. ¿Qué tipo de control de seguridad cumplen estos letreros?", ["Preventivo", "Detectivo", "Disuasivo", "Correctivo"], "Los letreros de advertencia desalientan a las personas de intentar una acción sin detenerlas físicamente, lo cual es la definición de un control disuasivo.", ["Los controles preventivos detienen físicamente una acción antes de que ocurra; un letrero solo desalienta.", "Los controles detectivos identifican incidentes después de que ocurren, no advierten a las personas de antemano.", null, "Los controles correctivos reparan el daño después de un incidente, cosa que un letrero de advertencia no hace."]],
  "x2": ["Tras una infección de malware, un administrador borra por completo el servidor afectado y lo restaura desde un respaldo limpio. ¿Qué categoría de control representa esta restauración?", ["Disuasivo", "Preventivo", "Detectivo", "Correctivo"], "Restaurar un sistema a un buen estado después de un incidente repara el daño, lo cual es un control correctivo.", ["Los controles disuasivos desalientan comportamientos; no reparan un sistema comprometido.", "Los controles preventivos detienen un incidente antes de que ocurra, no restauran después.", "Los controles detectivos solo identifican que algo ocurrió; no lo reparan.", null]],
  "x3": ["Un analista de riesgos calcula en dólares la expectativa de pérdida anualizada para justificar el costo de un control. ¿Qué tipo de evaluación de riesgos se está realizando?", ["Cualitativa", "Cuantitativa", "Inherente", "Residual"], "Asignar valores monetarios como la ALE es una evaluación cuantitativa; los métodos cualitativos usan en cambio calificaciones como alto o bajo.", ["La evaluación cualitativa usa calificaciones como alto o bajo, no cifras en dólares como la ALE.", null, "El riesgo inherente es el nivel de riesgo antes de los controles, no un método de evaluación.", "El riesgo residual es lo que queda después de los controles, no una técnica de evaluación."]],
  "x4": ["Un oficial de privacidad quiere que las personas controlen cómo se recopilan y usan sus datos personales. ¿Qué concepto respalda MÁS directamente este objetivo?", ["Disponibilidad", "No repudio", "Privacidad", "Integridad"], "Dar a las personas control sobre cómo se maneja su información personal es la idea central de la privacidad.", ["La disponibilidad se refiere a mantener los sistemas accesibles, no al control de los datos personales.", "El no repudio impide negar una acción; no trata sobre el control de los datos personales.", null, "La integridad se refiere a prevenir cambios no autorizados, no a quién controla los datos personales."]],
  "x5": ["La dirección revisa un riesgo de baja probabilidad y bajo impacto, documenta la decisión y elige no tomar ninguna otra acción. ¿Qué tratamiento del riesgo es este?", ["Mitigación", "Aceptación", "Evitación", "Transferencia"], "Documentar conscientemente un riesgo y decidir convivir con él, en lugar de actuar, es la aceptación del riesgo.", ["La mitigación consiste en agregar controles para reducir el riesgo, lo cual no se hizo aquí.", null, "La evitación consiste en detener por completo la actividad riesgosa, no en mantenerla como está.", "La transferencia traslada el riesgo a un tercero, como una aseguradora, lo cual no ocurrió."]],
  "x6": ["Una aplicación permite iniciar sesión solo cuando la solicitud proviene de una ubicación aprobada y rechaza todas las demás. ¿Qué factor de autenticación se está usando?", ["Algo que sabes", "Algo que tienes", "Algo que eres", "Algún lugar donde estás"], "Usar la ubicación del usuario para permitir o denegar el acceso es el factor de 'algún lugar donde estás' (ubicación).", ["Algo que sabes es una contraseña o un PIN, no la ubicación de la solicitud.", "Algo que tienes es un token o un dispositivo, no una ubicación.", "Algo que eres es un rasgo biométrico, no una ubicación.", null]],
  "x7": ["Un servidor de archivos usa discos redundantes y una fuente de energía de respaldo para seguir sirviendo archivos si falla un disco o la energía. ¿Qué principio de seguridad respalda esto?", ["Confidencialidad", "Integridad", "Disponibilidad", "No repudio"], "La redundancia mantiene un servicio accesible a pesar de la falla de un componente, lo que protege la disponibilidad.", ["La confidencialidad se refiere a mantener los datos en secreto, no a mantener el servicio en funcionamiento.", "La integridad se refiere a prevenir cambios no autorizados, no al tiempo de actividad.", null, "El no repudio se refiere a probar quién actuó, no a mantener un servicio disponible."]],
  "x8": ["Según la guía sobre el Código de Ética de ISC2, si dos cánones parecen contradecirse, ¿cómo debe resolver el conflicto un miembro?", ["Seguir el que sea más fácil", "Ignorar ambos cánones", "Pedirle al cliente que decida", "Aplicar los cánones en el orden en que están listados"], "Los cánones deben aplicarse en su orden de prioridad establecido cuando parecen contradecirse.", ["Elegir la opción más fácil ignora el orden de prioridad definido de los cánones.", "Ignorar los cánones contradice la obligación del miembro de respetarlos.", "Son los cánones, no el cliente, los que determinan cómo se resuelven los conflictos.", null]],
  "x9": ["Un empleado inserta una tarjeta inteligente e ingresa un PIN para iniciar sesión. ¿Qué factor de autenticación representa la tarjeta inteligente en sí?", ["Algo que sabes", "Algo que eres", "Algún lugar donde estás", "Algo que tienes"], "Una tarjeta inteligente física es un token que posees, así que es un factor de 'algo que tienes'; el PIN es 'algo que sabes'.", ["Algo que sabes se refiere al PIN, no a la tarjeta física.", "Algo que eres es un rasgo biométrico, no un objeto que se posee.", "Algún lugar donde estás es la ubicación, que la tarjeta no representa.", null]],
  "x10": ["Un equipo de seguridad documenta 'grupos del crimen organizado que buscan beneficio económico' como fuente de daño potencial. ¿Qué están identificando?", ["Una vulnerabilidad", "Un control", "Una amenaza", "Un activo"], "Un actor o evento que podría causar daño es una amenaza; una vulnerabilidad es la debilidad que explotaría.", ["Una vulnerabilidad es una debilidad, no el actor que la explotaría.", "Un control es una salvaguarda, no una fuente de daño.", null, "Un activo es algo de valor que se protege, no una fuente de daño."]],
  "x11": ["Una cerradura impide que una persona no autorizada entre a un cuarto de cableado. ¿Qué función de control cumple principalmente la cerradura?", ["Detectiva", "Correctiva", "Preventiva", "Compensatoria"], "Una cerradura detiene la acción no deseada antes de que ocurra, lo cual es una función de control preventiva.", ["Los controles detectivos identifican un evento después de que ocurre, no bloquean la entrada.", "Los controles correctivos reparan el daño después, no impiden la entrada.", null, "Un control compensatorio sustituye a otro; la cerradura impide el acceso directamente."]],
  "x12": ["Un administrador quiere confirmar que un archivo de configuración no ha sido alterado desde que se aprobó. ¿Qué técnica lo verifica MEJOR?", ["Comparar un hash criptográfico del archivo", "Cifrar el archivo con una clave pública", "Comprimir el archivo", "Cambiar el nombre del archivo"], "Un hash criptográfico cambia si cambia cualquier parte del contenido, así que hashes coincidentes prueban que el archivo no fue alterado.", [null, "El cifrado de clave pública protege la confidencialidad, no detecta alteraciones.", "La compresión solo reduce el tamaño y no revela manipulaciones.", "Cambiar el nombre de un archivo no verifica en absoluto que su contenido no haya cambiado."]],
  "x13": ["Después de que una empresa aplica controles para reducir un riesgo, todavía queda algo de riesgo. ¿Cómo se llama este riesgo restante?", ["Riesgo inherente", "Riesgo total", "Riesgo transferido", "Riesgo residual"], "El riesgo que queda después de aplicar los controles es el riesgo residual; el riesgo inherente es el nivel antes de los controles.", ["El riesgo inherente es el nivel antes de aplicar cualquier control, no lo que queda.", "El riesgo total es la exposición completa, no lo que sobra después de los controles.", "El riesgo transferido se traslada a otra parte, no es lo que permanece en la organización.", null]],
  "x14": ["Antes de evaluar el riesgo, un equipo cataloga los servidores, datos y aplicaciones de los que depende el negocio. ¿Cómo se llaman estos elementos?", ["Amenazas", "Vulnerabilidades", "Activos", "Controles"], "Las cosas de valor que la organización necesita proteger son sus activos.", ["Las amenazas son fuentes de daño, no los elementos valiosos que se catalogan.", "Las vulnerabilidades son debilidades, no los recursos de los que depende el negocio.", null, "Los controles son salvaguardas, no los recursos que se protegen."]],
  "x15": ["Los reguladores le piden a una empresa que explique cómo su modelo de IA llegó a una decisión de préstamo. ¿Qué cualidad de la IA confiable enfatiza esta solicitud?", ["Elasticidad", "Redundancia", "Rendimiento (throughput)", "Transparencia"], "Poder explicar cómo una IA llega a una decisión es transparencia, un elemento clave de la IA confiable.", ["La elasticidad es una propiedad de escalado de la nube, sin relación con explicar decisiones de IA.", "La redundancia respalda la disponibilidad, no la explicabilidad de las decisiones de IA.", "El throughput mide el volumen de procesamiento, no la capacidad de explicar decisiones.", null]],
  "x16": ["Un documento establece la configuración de seguridad mínima que debe cumplir cada laptop de la empresa. ¿Qué tipo de documento de gobernanza es este?", ["Guía", "Política", "Línea base", "Procedimiento"], "Una línea base define la configuración o el nivel de seguridad mínimo aceptable; una política expresa la intención de alto nivel.", ["Una guía es solo una recomendación, no una configuración mínima obligatoria.", "Una política expresa la intención de alto nivel, no una configuración mínima específica.", null, "Un procedimiento da instrucciones paso a paso, no un estándar de configuración mínima."]],
  "x17": ["Un minorista almacena y procesa datos de tarjetas de crédito de sus clientes. ¿Con qué conjunto de requisitos debe cumplir?", ["PCI DSS", "HIPAA", "GDPR", "SOX"], "PCI DSS regula el manejo de datos de tarjetas de pago; HIPAA cubre datos de salud y GDPR cubre datos personales de la UE.", [null, "HIPAA cubre la información de salud protegida, no los datos de tarjetas de pago.", "GDPR cubre los datos personales de la UE, no específicamente las tarjetas de pago.", "SOX trata los controles sobre los informes financieros, no los datos de titulares de tarjetas."]],
  "x18": ["Una organización define cuánto permitirá que un proyecto específico se desvíe de su apetito de riesgo declarado. Esta desviación aceptable es su:", ["Tolerancia al riesgo", "Transferencia del riesgo", "Registro de riesgos", "Evitación del riesgo"], "La tolerancia al riesgo es la variación aceptable alrededor del apetito de riesgo general para una actividad determinada.", [null, "La transferencia del riesgo lo traslada a un tercero; no es la desviación aceptable.", "Un registro de riesgos es una lista de riesgos, no una medida de la desviación aceptable.", "La evitación del riesgo elimina la actividad; no describe una variación aceptable."]],
  "x19": ["A una empresa le preocupa que un proveedor de software pueda introducir vulnerabilidades en el código que entrega. Este es un ejemplo de:", ["Amenaza interna", "Riesgo de terceros (cadena de suministro)", "Riesgo físico", "Riesgo residual"], "El riesgo que surge de vendedores y proveedores es riesgo de terceros o de la cadena de suministro; una amenaza interna proviene de dentro.", ["Una amenaza interna proviene de dentro de la organización, no de un proveedor.", null, "El riesgo físico se relaciona con instalaciones y hardware, no con código introducido por un proveedor.", "El riesgo residual es lo que queda después de los controles, no un riesgo que se origina en un proveedor."]],
  "x20": ["Un documento recomienda, pero no exige, que el personal use un gestor de contraseñas. ¿Qué tipo de documento de gobernanza es?", ["Política", "Estándar", "Procedimiento", "Guía"], "Las recomendaciones opcionales son guías; las políticas y los estándares son obligatorios.", ["Una política es obligatoria, pero este documento solo recomienda.", "Un estándar fija requisitos obligatorios, a diferencia de una recomendación opcional.", "Un procedimiento da pasos obligatorios, no consejos opcionales.", null]],
  "x21": ["¿Qué ley rige principalmente la protección de los datos personales de las personas en la Unión Europea?", ["PCI DSS", "HIPAA", "GLBA", "GDPR"], "El GDPR es el reglamento de la UE para la protección de datos personales; los demás cubren tarjetas de pago, salud y datos financieros de EE. UU.", ["PCI DSS regula los datos de tarjetas de pago, no los datos personales de la UE en general.", "HIPAA cubre la información de salud en EE. UU., no los datos personales de la UE en general.", "GLBA cubre a las instituciones financieras de EE. UU., no los datos personales de la UE.", null]],
  "x22": ["¿Qué grupo de una organización es responsable de fijar el apetito de riesgo?", ["La mesa de ayuda", "Los atacantes externos", "Los usuarios finales", "La alta dirección"], "Fijar el apetito de riesgo es una decisión de gobernanza que corresponde a la alta dirección y la junta directiva.", ["La mesa de ayuda se ocupa de tareas de soporte, no de fijar el apetito de riesgo de la organización.", "Los atacantes externos son una amenaza, no quienes toman decisiones en la organización.", "Los usuarios finales siguen la política; no fijan el apetito de riesgo.", null]],
  "x23": ["¿Qué métrica está diseñada para indicar el desempeño frente a una meta en lugar de advertir sobre una exposición al riesgo creciente?", ["Indicador clave de riesgo", "Objetivo de tiempo de recuperación", "Expectativa de pérdida anualizada", "Indicador clave de desempeño"], "Un KPI mide el avance hacia una meta; un KRI se elige específicamente para señalar un riesgo creciente.", ["Un indicador clave de riesgo advierte sobre un riesgo creciente, no sobre el desempeño frente a una meta.", "Un objetivo de tiempo de recuperación es una meta de continuidad, no una métrica de desempeño en este caso.", "La expectativa de pérdida anualizada es una estimación del costo del riesgo, no una medida de desempeño.", null]],
  "x24": ["¿Cuál de las siguientes es la MEJOR evidencia de que un programa de concientización de seguridad está cambiando el comportamiento de los empleados?", ["Cantidad de diapositivas de capacitación", "Total de empleados contratados", "Menor tasa de clics en simulaciones de phishing", "Cantidad de políticas redactadas"], "Una tasa de clics decreciente en las simulaciones de phishing muestra que el comportamiento está cambiando; contar diapositivas o políticas no.", ["Contar diapositivas mide el esfuerzo, no un cambio en el comportamiento de los empleados.", "La cantidad de empleados contratados no dice nada sobre el comportamiento de concientización.", null, "La cantidad de políticas redactadas no demuestra que el comportamiento haya cambiado."]],
  "x25": ["Un auditor descubre que el personal se está saltando un paso de aprobación obligatorio. ¿Qué documento debe definir ese requisito obligatorio a alto nivel?", ["Guía", "Política", "Boletín informativo", "Folleto de marketing"], "Los requisitos obligatorios se establecen en una política; las guías son solo recomendaciones y las demás opciones no son documentos de gobernanza.", ["Una guía es solo una recomendación, no un paso obligatorio.", null, "Un boletín informativo es una comunicación informal, no un documento de gobernanza.", "Un folleto de marketing es material promocional, no un documento de gobernanza."]],
  "x26": ["A un analista con todas las autorizaciones de seguridad se le niega el acceso a un proyecto clasificado que no tiene relación con sus funciones. ¿Qué principio impone esta restricción?", ["Separación de funciones", "Necesidad de saber (need to know)", "Inicio de sesión único", "Federación"], "La necesidad de saber limita el acceso a la información que una persona realmente requiere para su trabajo, aunque tenga la autorización de seguridad.", ["La separación de funciones divide una tarea entre personas; no trata de límites de acceso por tema.", null, "El inicio de sesión único es una comodidad de autenticación, no un principio que limite el acceso.", "La federación extiende la identidad entre organizaciones; no restringe según la necesidad."]],
  "x27": ["Un usuario inicia sesión en el sitio web de una empresa socia usando el proveedor de identidad de su propio empleador. ¿Qué hace esto posible?", ["La federación de identidades", "El control de acceso obligatorio", "La acumulación de privilegios", "El tailgating"], "La federación permite que una organización confíe en el proveedor de identidad de otra para que los usuarios inicien sesión entre dominios.", [null, "El control de acceso obligatorio impone etiquetas; no permite el inicio de sesión entre empresas.", "La acumulación de privilegios es un aumento no deseado de accesos, no un mecanismo de inicio de sesión.", "El tailgating es un ataque de entrada física, sin relación con el inicio de sesión federado."]],
  "x28": ["El primer día de un nuevo empleado, se le crean cuentas y accesos según el rol asignado. ¿Qué etapa del ciclo de vida de la identidad es esta?", ["Baja de accesos (deprovisioning)", "Revisión de accesos", "Recertificación", "Aprovisionamiento (provisioning)"], "Crear identidades y otorgar el acceso inicial es aprovisionamiento; la baja de accesos retira el acceso cuando alguien se va.", ["La baja de accesos retira el acceso cuando un usuario se va, lo opuesto a la incorporación.", "Una revisión de accesos comprueba los accesos existentes; no los crea el primer día.", "La recertificación confirma que los accesos existentes siguen siendo válidos, no la creación inicial.", null]],
  "x29": ["Un firewall permite tráfico solo en horario laboral, sin importar quién sea el usuario. ¿Qué tipo de control de acceso representa esto?", ["Discrecional", "Basado en roles", "Basado en reglas", "Obligatorio"], "El control basado en reglas aplica condiciones como la hora del día a todos; RBAC decidiría en cambio según el rol del usuario.", ["El control discrecional permite que los dueños decidan el acceso, no una regla de horario fija para todos.", "El control basado en roles decide según el rol del usuario, no por una condición de horario general.", null, "El control obligatorio usa etiquetas y autorizaciones de seguridad, no reglas por hora del día."]],
  "x30": ["¿Qué tipo de solución resguarda en una bóveda, rota y monitorea las credenciales usadas por las cuentas administrativas?", ["Gestión de accesos privilegiados (PAM)", "Inicio de sesión único", "Una VLAN de invitados", "Un honeypot"], "PAM protege, rota y audita específicamente las credenciales privilegiadas; SSO maneja los inicios de sesión comunes de los usuarios.", [null, "El inicio de sesión único simplifica el inicio de sesión de los usuarios; no resguarda credenciales de administrador.", "Una VLAN de invitados aísla el tráfico de visitantes, sin relación con las credenciales privilegiadas.", "Un honeypot es un sistema señuelo, no una herramienta de gestión de credenciales."]],
  "x31": ["Un atacante que carga cajas le pide a un empleado que le sostenga abierta la puerta de seguridad. ¿Qué amenaza es esta?", ["Phishing", "Tailgating", "Spoofing (suplantación)", "DDoS"], "Seguir a una persona autorizada a través de una puerta controlada es tailgating; el phishing y el spoofing no son formas de entrada física.", ["El phishing usa mensajes engañosos, no el acceso físico por una puerta.", null, "El spoofing falsifica una identidad en los datos, no es una entrada física por una puerta.", "Un DDoS inunda un servicio; no es una técnica de entrada física."]],
  "x32": ["Mover periódicamente a los empleados por distintos puestos sensibles ayuda a sacar a la luz fraudes ocultos. ¿Cómo se llama esta práctica?", ["Rotación de puestos", "Mínimo privilegio", "Federación", "Aprovisionamiento"], "La rotación de puestos mueve a las personas entre funciones para descubrir irregularidades que dependen de que una persona permanezca en el mismo lugar.", [null, "El mínimo privilegio limita los niveles de acceso; no es la práctica de rotar al personal.", "La federación vincula la identidad entre organizaciones, sin relación con la rotación de funciones.", "El aprovisionamiento crea cuentas y accesos, no rota al personal."]],
  "x33": ["Un sistema de credenciales registra cada entrada al centro de datos junto con la hora y la identidad. ¿Qué respalda principalmente este registro?", ["La prevención de la entrada", "El accounting y la auditoría del acceso", "El cifrado de las credenciales", "La baja de accesos"], "Mantener un registro de quién accedió a qué y cuándo es la función de accounting o auditoría.", ["Un registro de entradas documenta el acceso; por sí solo no impide la entrada.", null, "Cifrar las credenciales protege los datos de acceso, no el registro de quién entró.", "La baja de accesos retira el acceso; no es el registro de las entradas."]],
  "x34": ["En un sistema de control de acceso obligatorio (MAC), ¿por qué un usuario no puede simplemente compartir un archivo propio con un colega?", ["El acceso lo imponen etiquetas y autorizaciones de seguridad de todo el sistema, no la elección del usuario", "Ningún sistema operativo permite compartir archivos", "El colega no tiene nombre de usuario", "MAC solo se aplica a las impresoras"], "En MAC el sistema impone el acceso usando etiquetas y autorizaciones de seguridad definidas por la política, así que los dueños no pueden otorgar acceso por su cuenta.", [null, "Muchos sistemas permiten compartir archivos; la restricción es propia de MAC.", "No tener nombre de usuario no es la razón por la que MAC bloquea que el dueño comparta.", "MAC rige los datos y los sistemas en general, no solo las impresoras."]],
  "x35": ["Cada trimestre, los gerentes deben confirmar que cada miembro de su equipo sigue necesitando sus accesos actuales. ¿Cómo se llama este proceso?", ["Recertificación de accesos", "Inicio de sesión único", "Aprovisionamiento", "Rotación de contraseñas"], "Confirmar periódicamente que el acceso sigue siendo apropiado es la recertificación o revisión de accesos.", [null, "El inicio de sesión único es una función de autenticación, no una verificación periódica de accesos.", "El aprovisionamiento otorga el acceso inicial; no confirma que se siga necesitando.", "La rotación de contraseñas cambia las credenciales, no verifica si el acceso sigue siendo necesario."]],
  "x36": ["Un empleado pasa de finanzas a marketing, pero conserva su antiguo acceso al sistema financiero. ¿Qué debe prevenir la baja de accesos al transferirse?", ["El tailgating", "Un DDoS", "La clasificación de datos", "La acumulación de privilegios"], "Acumular accesos innecesarios a lo largo de los cambios de rol es la acumulación de privilegios, que se previene retirando los accesos oportunamente al transferirse.", ["El tailgating es un ataque de entrada física, no un problema de acumulación de accesos.", "Un DDoS es un ataque a la disponibilidad, sin relación con los accesos que quedan tras una transferencia.", "La clasificación de datos etiqueta la información; no tiene que ver con la acumulación de accesos.", null]],
  "x37": ["Para reducir el fraude interno, la persona que solicita un nuevo acceso no debe ser la misma que lo aprueba. ¿Qué principio se aplica?", ["Mínimo privilegio", "Separación de funciones", "Federación", "Elasticidad"], "Dividir la solicitud y la aprobación entre dos personas es separación de funciones; el mínimo privilegio limita cuánto acceso se otorga.", ["El mínimo privilegio limita cuánto acceso se otorga, no quién lo aprueba.", null, "La federación vincula la identidad entre organizaciones, no separa las aprobaciones.", "La elasticidad es una propiedad de escalado de la nube, sin relación con las funciones de aprobación."]],
  "x38": ["Un técnico de mesa de ayuda se conecta de forma remota a un escritorio Windows usando Remote Desktop Protocol. ¿Qué puerto predeterminado usa?", ["22", "443", "3389", "53"], "RDP usa TCP 3389 de forma predeterminada; el 22 es SSH, el 443 es HTTPS y el 53 es DNS.", ["El puerto 22 lo usa SSH, no Remote Desktop Protocol.", "El puerto 443 lo usa HTTPS, no RDP.", null, "El puerto 53 lo usa DNS, no RDP."]],
  "x39": ["¿Qué puerto usa normalmente una consulta estándar de nombres DNS?", ["80", "53", "25", "389"], "La resolución de nombres DNS usa el puerto 53; el puerto 80 es HTTP, el 25 es SMTP para correo y el 389 es acceso a directorios LDAP.", ["El puerto 80 lo usa HTTP, no las consultas DNS.", null, "El puerto 25 lo usa SMTP, no DNS.", "El puerto 389 lo usa LDAP, no DNS."]],
  "x40": ["¿Qué puerto usa comúnmente el correo que se transfiere entre servidores de correo?", ["110", "143", "25", "3389"], "SMTP usa el puerto 25 para el correo entre servidores; el 110 es POP3 y el 143 es IMAP, ambos para la recuperación de correo.", ["El puerto 110 lo usa POP3 para recuperar correo, no para el envío entre servidores.", "El puerto 143 lo usa IMAP para recuperar correo, no para enviarlo entre servidores.", null, "El puerto 3389 lo usa RDP, no la transferencia de correo."]],
  "x41": ["Una empresa guarda registros sensibles en su nube privada, pero se expande a una nube pública durante los picos de demanda. ¿Qué modelo de implementación es este?", ["Pública", "Comunitaria", "Híbrida", "Privada"], "Combinar nubes privadas y públicas que funcionan en conjunto es una implementación de nube híbrida.", ["Una nube pública por sí sola no incluye la parte de nube privada de la empresa.", "Una nube comunitaria la comparten organizaciones similares; no es una combinación de privada y pública.", null, "Una nube privada por sí sola excluye la expansión a la nube pública descrita."]],
  "x42": ["Un desarrollador despliega código en un servicio donde el proveedor gestiona el sistema operativo y el runtime, pero el desarrollador gestiona la aplicación. ¿Qué modelo de servicio es este?", ["IaaS", "PaaS", "SaaS", "On-premises (local)"], "PaaS proporciona una plataforma gestionada para aplicaciones mientras el proveedor se encarga del sistema operativo y del runtime subyacentes.", ["En IaaS el cliente gestiona el sistema operativo, a diferencia del servicio descrito.", null, "En SaaS el proveedor gestiona toda la aplicación, no solo la plataforma.", "On-premises significa que el cliente opera toda la infraestructura por su cuenta."]],
  "x43": ["Un centro de datos aplica políticas de seguridad entre cargas de trabajo individuales, no solo en el borde de la red. ¿Cómo se llama este enfoque?", ["Microsegmentación", "Reenvío de puertos", "Traducción de direcciones de red", "Difusión (broadcasting)"], "Aplicar controles entre cargas de trabajo individuales es microsegmentación, una forma de segmentación más granular.", [null, "El reenvío de puertos redirige tráfico específico, no aplica políticas entre cargas de trabajo.", "La traducción de direcciones de red reasigna direcciones; no segmenta cargas de trabajo.", "La difusión envía tráfico a todos los hosts, lo opuesto a aislar cargas de trabajo."]],
  "x44": ["Un atacante retransmite en secreto, y puede alterar, los mensajes entre dos partes que creen estar comunicándose directamente. ¿Qué ataque es este?", ["Denegación de servicio", "Envenenamiento de datos", "Tailgating", "Man-in-the-middle (intermediario)"], "Interceptar y posiblemente alterar el tráfico entre dos partes es un ataque man-in-the-middle.", ["Una denegación de servicio afecta la disponibilidad; no retransmite mensajes en secreto.", "El envenenamiento de datos corrompe los datos de entrenamiento, no las comunicaciones en vivo entre las partes.", "El tailgating es un ataque de entrada física, no una interceptación de mensajes.", null]],
  "x45": ["¿Qué dispositivo filtra el tráfico entre segmentos de red según reglas sobre direcciones, puertos y protocolos?", ["Switch", "Firewall", "Hub", "Punto de acceso inalámbrico"], "Un firewall aplica reglas para permitir o bloquear el tráfico entre segmentos; un switch o un hub solo reenvían tramas.", ["Un switch reenvía tramas dentro de un segmento; no filtra según reglas.", null, "Un hub simplemente repite el tráfico hacia todos los puertos sin filtrar.", "Un punto de acceso inalámbrico proporciona conectividad, no filtrado basado en reglas."]],
  "x46": ["Un trabajador remoto necesita un túnel cifrado hacia la red corporativa a través de internet pública. ¿Qué tecnología lo proporciona?", ["VLAN", "DMZ", "VPN", "NAT"], "Una VPN crea un túnel cifrado a través de redes no confiables; una VLAN y una DMZ son segmentos de red, no túneles.", ["Una VLAN segmenta una red local; no crea un túnel a través de internet.", "Una DMZ es una subred filtrada para servicios públicos, no un túnel cifrado.", null, "NAT traduce direcciones; no crea un túnel cifrado."]],
  "x47": ["A un cliente de la nube se le factura según la cantidad exacta de almacenamiento y cómputo que consume. ¿Qué característica de la nube es esta?", ["Agrupación de recursos", "Servicio medido", "Amplio acceso a la red", "Multiinquilino (multitenancy)"], "Medir y facturar según el uso real es la característica de servicio medido de la computación en la nube.", ["La agrupación de recursos comparte la infraestructura entre inquilinos; no es la facturación por uso.", null, "El amplio acceso a la red significa acceder a los servicios por la red, no medir el consumo.", "Multitenancy significa que muchos clientes comparten recursos, no que se facture por uso."]],
  "x48": ["En una implementación de Infraestructura como Servicio (IaaS), ¿quién es responsable de aplicar parches al sistema operativo invitado?", ["El proveedor de la nube", "Nadie", "El ISP del usuario final", "El cliente"], "En IaaS el proveedor opera la infraestructura física mientras el cliente gestiona desde el sistema operativo hacia arriba, incluidos los parches.", ["En IaaS el proveedor gestiona la infraestructura física y el hipervisor, no el sistema operativo invitado.", "Parchear el sistema operativo invitado es una responsabilidad definida, así que no queda en manos de nadie.", "El ISP proporciona conectividad y no aplica parches al sistema operativo invitado de un cliente.", null]],
  "x49": ["Llegan a la red paquetes que declaran una dirección IP de origen que en realidad no pertenece al remitente, con el fin de evadir un filtro. ¿Qué técnica es esta?", ["Spoofing (suplantación)", "Segmentación", "Cifrado", "Balanceo de carga"], "Falsificar una dirección de origen para aparentar ser un host confiable es spoofing.", [null, "La segmentación divide una red; no es el acto de falsificar direcciones de origen.", "El cifrado protege la confidencialidad de los datos, no falsifica direcciones de origen.", "El balanceo de carga distribuye el tráfico; no falsifica direcciones de origen."]],
  "x50": ["¿En qué capa del modelo TCP/IP operan TCP y UDP, usando números de puerto para identificar aplicaciones?", ["Aplicación", "Transporte", "Internet", "Enlace"], "TCP y UDP, con sus números de puerto, operan en la capa de transporte del modelo TCP/IP.", ["La capa de aplicación maneja servicios como HTTP, no directamente los puertos TCP/UDP.", null, "La capa de internet maneja el direccionamiento IP y el enrutamiento, no los números de puerto.", "La capa de enlace maneja la entrega local de tramas, no los puertos de transporte."]],
  "x51": ["Los analistas aíslan de la red una laptop infectada para evitar que el malware se propague a otros sistemas. ¿Qué fase de respuesta a incidentes es esta?", ["Detección", "Contención", "Recuperación", "Preparación"], "Limitar la propagación de un incidente activo es contención; la recuperación viene después, cuando se restauran los sistemas.", ["La detección es reconocer el incidente, lo cual ya ocurrió antes de aislar el equipo.", null, "La recuperación restablece los sistemas a la normalidad después de eliminar la amenaza, no en este momento.", "La preparación ocurre antes de cualquier incidente, no durante una respuesta activa."]],
  "x52": ["Dos sistemas comparten la misma clave secreta para cifrar y descifrar grandes cantidades de datos rápidamente. ¿Qué tipo de cifrado es este?", ["Asimétrico", "Hashing", "Simétrico", "Esteganografía"], "Usar una sola clave secreta compartida tanto para cifrar como para descifrar es cifrado simétrico; el asimétrico usa un par de claves.", ["El cifrado asimétrico usa un par de claves pública y privada, no una sola clave compartida.", "El hashing es unidireccional y no descifra datos.", null, "La esteganografía oculta datos dentro de otros datos; no es cifrado con clave compartida."]],
  "x53": ["Una empresa decide que su sistema de pedidos debe volver a operar dentro de las cuatro horas siguientes a una interrupción. ¿Qué métrica expresa esta meta?", ["Objetivo de punto de recuperación", "Tiempo medio entre fallas", "Tasa anualizada de ocurrencia", "Objetivo de tiempo de recuperación"], "El tiempo de inactividad máximo aceptable antes de la restauración es el objetivo de tiempo de recuperación; el RPO mide la pérdida de datos aceptable.", ["Un objetivo de punto de recuperación mide la pérdida de datos aceptable, no el tiempo de inactividad.", "El tiempo medio entre fallas mide la confiabilidad, no las metas de restauración.", "La tasa anualizada de ocurrencia estima la frecuencia de los eventos, no el tiempo de inactividad.", null]],
  "x54": ["Antes de redactar un plan de continuidad, una empresa identifica qué funciones son más críticas y el impacto de perderlas. ¿Cómo se llama este análisis?", ["Análisis de impacto al negocio (BIA)", "Prueba de penetración", "Revisión de accesos", "Ciclo de parches"], "Un análisis de impacto al negocio identifica las funciones críticas y el efecto de perderlas, y alimenta las decisiones de RTO y RPO.", [null, "Una prueba de penetración busca vulnerabilidades, no la criticidad de las funciones.", "Una revisión de accesos comprueba los permisos de los usuarios, no el impacto en las funciones del negocio.", "Un ciclo de parches programa actualizaciones; no analiza el impacto al negocio."]],
  "x55": ["Un cambio propuesto a una regla del firewall debe revisarse y aprobarse antes de aplicarse a los sistemas de producción. ¿Qué proceso rige esto?", ["Gestión de cambios", "Respuesta a incidentes", "Clasificación de datos", "Federación"], "Revisar y aprobar los cambios antes de que lleguen a producción es gestión de cambios, lo que reduce interrupciones y errores.", [null, "La respuesta a incidentes maneja incidentes activos, no cambios planificados en producción.", "La clasificación de datos etiqueta la información; no aprueba cambios.", "La federación vincula la identidad entre organizaciones, sin relación con la aprobación de cambios."]],
  "x56": ["Una política establece que los registros financieros deben conservarse durante siete años y luego destruirse de forma segura. ¿Qué concepto de seguridad de datos es este?", ["Retención de datos", "Cifrado", "Segmentación", "No repudio"], "Las reglas sobre cuánto tiempo conservar los datos antes de desecharlos son retención de datos; el cifrado los protege, pero no fija un plazo.", [null, "El cifrado protege la confidencialidad de los datos, pero no fija un plazo de conservación y destrucción.", "La segmentación aísla redes; no rige cuánto tiempo se conservan los datos.", "El no repudio prueba quién actuó; no tiene que ver con los periodos de retención."]],
  "x57": ["Después de contener una brecha, el equipo elimina el malware del atacante y cierra la vulnerabilidad que se explotó. ¿Qué fase es esta?", ["Detección", "Erradicación", "Preparación", "Lecciones aprendidas"], "Eliminar la amenaza y su causa raíz del entorno es erradicación, que sigue a la contención.", ["La detección reconoce el incidente; aquí el malware ya fue encontrado.", null, "La preparación ocurre antes de los incidentes, no mientras se elimina una amenaza activa.", "Las lecciones aprendidas son la fase de revisión final, después de la erradicación y la recuperación."]],
  "x58": ["Una organización mantiene una instalación duplicada, totalmente equipada y en funcionamiento, lista para asumir las operaciones casi de inmediato. ¿Qué opción de recuperación es esta?", ["Sitio frío (cold site)", "Sitio tibio (warm site)", "Sitio caliente (hot site)", "Acuerdo recíproco"], "Un hot site está totalmente equipado y en funcionamiento para que las operaciones se transfieran rápidamente; un cold site tiene poco o ningún equipo listo.", ["Un cold site tiene poco equipo listo y no puede asumir las operaciones de inmediato.", "Un warm site está parcialmente equipado y requiere configuración antes de asumir las operaciones.", null, "Un acuerdo recíproco comparte el sitio de otra organización, no es un duplicado listo."]],
  "x59": ["Un equipo escanea los sistemas con regularidad, prioriza los hallazgos según el riesgo y da seguimiento a su corrección a lo largo del tiempo. ¿Cómo se llama este proceso continuo?", ["Gestión de vulnerabilidades", "Erradicación de incidentes", "Etiquetado de datos", "Congelamiento de cambios"], "El ciclo continuo de encontrar, priorizar y corregir debilidades es la gestión de vulnerabilidades.", [null, "La erradicación de incidentes elimina una amenaza específica; no es el ciclo continuo de escaneo.", "El etiquetado de datos clasifica la información; no encuentra ni corrige debilidades.", "Un congelamiento de cambios detiene los cambios; no es la corrección de vulnerabilidades."]],
  "x60": ["Un analista del SOC revisa las alertas entrantes del SIEM para decidir cuáles requieren investigación y cuáles son falsos positivos. ¿Cómo se llama esta actividad?", ["Triaje de eventos", "Rotación de respaldos", "Rotación de claves", "Aprovisionamiento"], "Clasificar y priorizar alertas para decidir qué investigar es el triaje de eventos.", [null, "La rotación de respaldos gestiona los medios de respaldo, no la investigación de alertas.", "La rotación de claves cambia las claves criptográficas, sin relación con la revisión de alertas.", "El aprovisionamiento crea cuentas y accesos, no prioriza alertas."]],
  "x61": ["Un ransomware cifra los recursos compartidos de archivos de una empresa y el personal no puede abrir ningún documento. Los registros muestran que ningún dato salió de la red. ¿Qué principio de seguridad se vio afectado más directamente?", ["Confidencialidad","No repudio","Disponibilidad","Autenticación"], "Los archivos siguen existiendo pero no se pueden usar, lo que es una pérdida de disponibilidad. La confidencialidad es tentadora porque el ransomware suele asociarse con el robo de datos, pero aquí no se divulgó nada.", ["La confidencialidad trata de la divulgación no autorizada, y los registros muestran que no se sacó ningún dato.","El no repudio demuestra quién realizó una acción; no es lo que interrumpió el cifrado.",null,"La autenticación verifica identidades; el ataque no cambió la forma en que los usuarios demuestran quiénes son."]],
  "x62": ["Roban de un auto una laptop con una hoja de cálculo sin cifrar que contiene nombres y números de cuenta de clientes. ¿Qué principio de seguridad está más en riesgo?", ["Confidencialidad","Disponibilidad","Integridad","Rendición de cuentas"], "Datos sensibles sin cifrar en manos equivocadas representan una pérdida de confidencialidad. La disponibilidad es tentadora porque la laptop ya no está, pero el daño mayor es que personas no autorizadas pueden leer los datos.", [null,"Puede haber otras copias de los datos disponibles; la principal preocupación es quién puede leerlos ahora.","Nada indica que los datos se hayan alterado; el peligro es que el ladrón los vea.","La rendición de cuentas rastrea las acciones de los usuarios en los sistemas, lo que no es el problema central en un robo de datos."]],
  "x63": ["Un atacante en la ruta de red cambia el monto de una transferencia bancaria en línea de 100 a 10 000 antes de que llegue al banco. ¿Qué principio de seguridad se violó?", ["Confidencialidad","Disponibilidad","Privacidad","Integridad"], "La integridad significa que los datos no se alteran sin autorización, y cambiar el monto de la transferencia la viola. La confidencialidad es tentadora porque el atacante vio el mensaje, pero el daño viene de la modificación.", ["El problema no es que alguien leyera la transferencia, sino que se cambió su contenido.","La transferencia igual se realizó, así que el servicio no quedó fuera de servicio.","La privacidad trata del manejo de datos personales, no de cambios no autorizados en una transacción.",null]],
  "x64": ["Un sitio web pide a los usuarios una contraseña y luego la respuesta a una pregunta de seguridad, como el nombre de su primera mascota. ¿Por qué esto NO cuenta como autenticación multifactor?", ["Las preguntas de seguridad nunca se guardan de forma segura","Ambos son algo que el usuario sabe","La contraseña debe ingresarse en segundo lugar","Solo los factores biométricos cuentan para la autenticación multifactor"], "La MFA exige factores de categorías distintas, como algo que sabes más algo que tienes o eres, y aquí ambos son conocimiento. La idea de que solo cuenta la biometría es tentadora, pero los factores de posesión como los tokens también son válidos.", ["La forma de guardarlas no define si los factores son de distinto tipo; ambos siguen siendo conocimiento.",null,"El orden en que se ingresan los factores no influye en si cuentan como varios factores.","Algo que tienes, como un token, también cuenta; la biometría es solo uno de los tipos de factor."]],
  "x65": ["Un servidor está valuado en USD 200 000. Los analistas estiman que una inundación destruiría el 25% de su valor. ¿Cuál es la expectativa de pérdida única (SLE) por una inundación?", ["USD 25 000","USD 50 000","USD 200 000","USD 800 000"], "La SLE es el valor del activo por el factor de exposición: 200 000 x 0.25 = 50 000. Usar el valor total del activo es tentador, pero se espera que la inundación destruya solo una cuarta parte.", ["Eso correspondería a un factor de exposición del 12.5%, no al 25% que estimaron los analistas.",null,"Es el valor total del activo, que ignora el factor de exposición del 25%.","Esto multiplica el valor del activo por 4 en lugar de por el 25%."]],
  "x66": ["Un riesgo tiene una expectativa de pérdida única de USD 50 000 y se espera que ocurra una vez cada cinco años. Un control que eliminaría el riesgo cuesta USD 15 000 por año. Basándose solo en la expectativa de pérdida anualizada, ¿qué debe concluir la gerencia?", ["El control se justifica claramente porque la expectativa de pérdida única de USD 50 000 supera su costo anual","La pérdida anual esperada es de USD 250 000, así que el control es barato","El control ahorra exactamente USD 35 000 por año","El control cuesta más por año que la pérdida anual esperada de USD 10 000"], "ALE = SLE x ARO = 50 000 x 0.2 = 10 000 por año, menos que los 15 000 anuales del control. Comparar el costo del control con la SLE es tentador, pero los costos se deben comparar sobre la misma base anual.", ["La SLE es la pérdida de un solo evento; compararla con un costo anual ignora lo poco frecuente que es el evento.","Esto multiplica por 5 en lugar de por una ARO de 0.2 y exagera la pérdida anual.","Esto resta el costo del control a la SLE, mezclando una pérdida única con un costo anual.",null]],
  "x67": ["Después de revisar los riesgos, una empresa cancela su plan de guardar datos de pago de clientes en sus propios servidores y nunca inicia el proyecto. ¿Qué tratamiento del riesgo es este?", ["Evitar","Mitigar","Transferir","Aceptar"], "Dejar de hacer la actividad que genera el riesgo es evitar el riesgo. Mitigar es tentador porque también reduce el riesgo, pero mantiene la actividad y agrega controles.", [null,"Mitigar implicaría mantener el proyecto y agregar controles para reducir el riesgo.","Transferir pasaría el impacto financiero a otra parte, como una aseguradora.","Aceptar implicaría seguir con el proyecto y convivir conscientemente con el riesgo."]],
  "x68": ["¿Cuál de los siguientes es un ejemplo de control de seguridad técnico (lógico)?", ["Un programa anual obligatorio de concientización en seguridad para todo el personal","Una puerta con llave en la sala de servidores","Una regla de firewall que bloquea el tráfico entrante de escritorio remoto","Una verificación de antecedentes para nuevos empleados"], "Los controles técnicos se implementan en hardware o software, como las reglas de firewall. La puerta con llave es tentadora porque también bloquea el acceso, pero es un control físico.", ["La capacitación es un control administrativo que actúa a través de las personas y las políticas.","Una puerta con llave es un control físico que protege un espacio.",null,"La verificación de antecedentes es un control administrativo que se aplica al contratar."]],
  "x69": ["El empleador de un miembro de ISC2 le pide que guarde silencio sobre una falla de seguridad conocida en un dispositivo médico que podría dañar a pacientes. ¿Qué canon del Código de Ética de ISC2 debe guiar primero al miembro?", ["Prestar un servicio diligente y competente a los mandantes","Promover y proteger la profesión","Actuar de forma honorable, honesta, justa, responsable y legal con el empleador y con cada colega involucrado","Proteger a la sociedad, el bien común, la confianza pública necesaria y la infraestructura"], "Los cánones se aplican en orden, y proteger a la sociedad y el bien común va primero cuando los deberes chocan. Servir a los mandantes es tentador porque lo pide el empleador, pero ese canon tiene menor prioridad.", ["Servir a los mandantes importa, pero está por debajo de proteger a la sociedad cuando ambos chocan.","Promover la profesión es el canon de menor prioridad y no atiende primero el daño al público.","Actuar de forma honorable aplica, pero los cánones tienen orden y proteger a la sociedad va primero.",null]],
  "x70": ["Un miembro de ISC2 acepta un trabajo pagado para evaluar un sistema de control industrial, un campo en el que no tiene experiencia, y no se lo dice al cliente. ¿Con qué canon choca más directamente?", ["Proteger a la sociedad, el bien común y la infraestructura","Prestar un servicio diligente y competente a los mandantes","Promover y proteger la profesión","No viola ningún canon porque el cliente aceptó pagar"], "Aceptar trabajo fuera de la propia competencia sin decirlo incumple el deber de prestar un servicio diligente y competente a los mandantes. Proteger a la sociedad es tentador porque los sistemas de control son críticos, pero la falta directa es con el cliente.", ["Un mal trabajo podría afectar a la sociedad con el tiempo, pero la falla directa es con el cliente atendido.",null,"La profesión podría verse afectada de forma indirecta, pero el problema principal es el servicio incompetente al cliente.","El pago no justifica ocultarle al cliente la falta de competencia."]],
  "x71": ["Un modelo de contratación entrenado con diez años de decisiones anteriores califica siempre más bajo a los postulantes de una región, aunque ningún atacante tocó el sistema. ¿Cuál es la causa más probable?", ["Envenenamiento de datos por un atacante externo","Robo del modelo por parte de un competidor","Sesgo en los datos históricos de entrenamiento","Un ataque de denegación de servicio contra el modelo"], "Un modelo entrenado con decisiones históricas sesgadas aprende y repite ese sesgo, lo que afecta la equidad y la confianza. El envenenamiento de datos es tentador porque también corrompe los datos de entrenamiento, pero requiere un atacante deliberado.", ["El envenenamiento implica que alguien inyecte datos malos a propósito, y aquí no hubo atacante.","El robo del modelo lo copia; no cambiaría cómo califica a los postulantes.",null,"Un ataque de denegación de servicio deja el modelo fuera de servicio en lugar de sesgar sus resultados."]],
  "x72": ["Una empresa rediseña su formulario de registro para pedir solo el correo del cliente en lugar del nombre completo, la fecha de nacimiento y el domicilio, porque el servicio no necesita el resto. ¿Qué principio de privacidad se aplica?", ["Minimización de datos","Retención de datos","No repudio","Clasificación de datos"], "La minimización de datos significa recolectar solo los datos personales necesarios para un propósito declarado. La retención es tentadora porque también limita los datos, pero trata de cuánto tiempo se guardan.", [null,"La retención define cuánto tiempo se guardan los datos, no cuántos se recolectan desde el inicio.","El no repudio demuestra quién realizó una acción; no tiene relación con recolectar menos datos.","La clasificación etiqueta los datos según su sensibilidad, pero no limita qué se recolecta."]],
  "x73": ["Cinco administradores comparten una sola cuenta llamada admin para administrar un servidor crítico. ¿Por qué este esquema impide el no repudio?", ["Las acciones no se pueden atribuir a una persona específica","Las cuentas compartidas no pueden usar cifrado","El sistema operativo no puede registrar eventos de las cuentas compartidas","Las cuentas compartidas siempre tienen contraseñas más débiles"], "El no repudio exige que las acciones se atribuyan a una persona única que no pueda negarlas, algo imposible con una cuenta compartida. Decir que el servidor no puede registrar es tentador, pero sí registra; solo que los registros no muestran quién estaba detrás de la cuenta.", [null,"Con una cuenta compartida se puede seguir usando cifrado; el problema es identificar quién actuó.","El servidor puede seguir registrando acciones, pero los registros solo muestran el nombre de la cuenta compartida.","La fortaleza de la contraseña no tiene relación con demostrar qué persona realizó una acción."]],
  "x74": ["Se instala una cerca alta con un portón cerrado con llave alrededor del generador de respaldo de una empresa para impedir que las personas lleguen a él. ¿Cómo se clasifica mejor este control?", ["Técnico y detectivo","Administrativo y correctivo","Físico y preventivo","Físico y detectivo"], "Una cerca es una barrera física que detiene el acceso no autorizado antes de que ocurra, así que es física y preventiva. Físico y detectivo es tentador, pero la detección sería algo como una cámara o una alarma.", ["Una cerca no se implementa en software, y detiene el acceso en lugar de detectarlo.","Una cerca no es una política, y actúa antes de un incidente en vez de corregirlo después.",null,"La cerca es física, pero bloquea el acceso en lugar de detectarlo o registrarlo."]],
  "x75": ["Un documento establece que todos los sistemas de la empresa deben usar AES con claves de 256 bits para cifrar los datos almacenados. ¿Qué tipo de documento de gobierno es este?", ["Política","Estándar","Directriz","Procedimiento"], "Los estándares fijan requisitos obligatorios y específicos, como un algoritmo y un largo de clave determinados. La política es tentadora porque también es obligatoria, pero expresa objetivos generales, no tecnologías específicas.", ["Una política expresa una intención general, como proteger los datos, sin nombrar algoritmos específicos.",null,"Una directriz es una recomendación, mientras que este documento hace obligatoria una tecnología específica.","Un procedimiento da instrucciones paso a paso, no una elección obligatoria de tecnología."]],
  "x76": ["Una clínica de Estados Unidos guarda y comparte historias clínicas de pacientes y, por ley, debe proteger esa información de salud. ¿Qué regulación aplica más directamente?", ["PCI DSS","GDPR","SOX","HIPAA"], "HIPAA es la ley de Estados Unidos que protege la privacidad y la seguridad de la información de salud de los pacientes. El GDPR es tentador porque es una gran ley de privacidad, pero aplica a datos personales de la UE.", ["PCI DSS cubre datos de tarjetas de pago, no historias clínicas.","El GDPR protege datos personales de personas en la UE, no específicamente historias clínicas de Estados Unidos.","SOX regula los informes financieros de empresas que cotizan en bolsa, no los datos de salud de pacientes.",null]],
  "x77": ["Un comercio pregunta por qué debe cumplir PCI DSS si ningún gobierno lo aprobó como ley. ¿Cuál es la mejor respuesta?", ["Es una ley federal de privacidad aprobada por el Congreso que aplica a todas las empresas de todos los países","Es un estándar de la industria al que el comercio se obliga mediante sus acuerdos con las marcas de tarjetas y los bancos","Es una guía opcional sin consecuencias si se ignora","Solo aplica a las empresas que ya sufrieron una filtración"], "PCI DSS es un requisito contractual: los comercios lo aceptan en sus acuerdos para aceptar tarjetas, y no cumplirlo puede traer multas o la pérdida del procesamiento de tarjetas. Decir que es opcional es tentador porque no es una ley, pero los contratos lo hacen obligatorio.", ["PCI DSS no es una ley aprobada por ningún gobierno, aunque se exige ampliamente.",null,"Ignorarlo puede traer multas o la pérdida de la posibilidad de aceptar tarjetas, así que no carece de consecuencias.","Aplica a cualquier organización que guarde, procese o transmita datos de titulares de tarjetas, haya tenido filtraciones o no."]],
  "x78": ["Un analista de seguridad descubre un riesgo grave en la aplicación de clientes del departamento de ventas. ¿Quién debería asignarse normalmente como dueño de este riesgo?", ["El gerente de negocio responsable de la aplicación de ventas","El analista de seguridad que descubrió y documentó el riesgo durante las pruebas","El auditor externo","El equipo de mesa de ayuda"], "Los dueños del riesgo son los líderes de negocio responsables del activo o proceso, porque deciden cómo se trata el riesgo. El analista es tentador porque conoce mejor el riesgo, pero seguridad asesora y el negocio es dueño de la decisión.", [null,"Encontrar un riesgo no hace que el analista sea responsable de la decisión de negocio sobre él.","Los auditores evalúan e informan de forma independiente; ser dueños de riesgos comprometería esa independencia.","La mesa de ayuda atiende a los usuarios y no tiene autoridad sobre los riesgos de negocio de la aplicación."]],
  "x79": ["Una empresa negocia un contrato con un proveedor que alojará los datos de sus clientes. ¿Qué cláusula del contrato le permite a la empresa verificar después los controles de seguridad del proveedor?", ["Una cláusula de no competencia","Una cláusula de fuerza mayor","Una cláusula de propiedad intelectual","Una cláusula de derecho de auditoría"], "Una cláusula de derecho de auditoría le da al cliente el derecho de evaluar los controles del proveedor, lo que apoya la gestión del riesgo de terceros. La fuerza mayor es tentadora porque también aparece en contratos con proveedores, pero solo trata eventos fuera del control de las partes.", ["Una cláusula de no competencia limita la actividad comercial competidora, no la verificación de seguridad.","La fuerza mayor excusa el incumplimiento ante eventos como desastres naturales; no da derechos de auditoría.","Una cláusula de propiedad intelectual define quién es dueño del trabajo creado, no cómo se revisan los controles.",null]],
  "x80": ["Un gran proveedor de nube no permite que clientes individuales realicen auditorías en sitio de sus centros de datos. ¿Qué debe pedir el cliente en su lugar para obtener garantías sobre los controles del proveedor?", ["El folleto comercial público del proveedor que describe sus certificaciones de seguridad y sus centros de datos","Una copia del manual de empleados del proveedor","Un informe de atestación independiente de terceros, como un SOC 2 Tipo II","Nada, porque los proveedores de nube no se pueden evaluar"], "Los informes de atestación independientes, como SOC 2 Tipo II, muestran que un auditor probó los controles del proveedor durante un período. Suponer que no se puede evaluar al proveedor es tentador, pero los informes de terceros existen justamente para esta situación.", ["El material comercial no está verificado de forma independiente y no da garantías confiables.","Un manual de empleados describe reglas para el personal, no controles de seguridad probados.",null,"Los proveedores se pueden evaluar mediante informes independientes aunque no se permitan auditorías en sitio."]],
  "x81": ["El personal del equipo de finanzas que aprueba transferencias bancarias es blanco frecuente de ataques de compromiso de correo empresarial. ¿Cuál es la forma más eficaz de ajustar el programa de concientización para ellos?", ["Enviarles la misma presentación anual general que reciben todos los demás empleados, sin cambios","Excluirlos de las simulaciones de phishing para evitarles estrés","Dar capacitación según el rol, enfocada en el fraude de pagos y en los pasos de verificación","Capacitar solo al departamento de TI sobre fraude de pagos"], "La capacitación según el rol da a los grupos de alto riesgo contenido adaptado a las amenazas que realmente enfrentan, como verificar solicitudes de cambio de datos de pago. La presentación anual genérica es tentadora porque es fácil, pero rara vez cambia el comportamiento ante riesgos especializados.", ["La capacitación anual genérica no atiende los patrones de fraude específicos que enfrenta este equipo.","Excluirlos de las simulaciones le quita práctica al grupo con mayor riesgo.",null,"El personal de TI no aprueba pagos, así que capacitar solo a TI deja sin preparación al equipo atacado."]],
  "x82": ["En tres trimestres, el tiempo promedio para parchar vulnerabilidades críticas subió de 10 a 30 días, mientras el presupuesto de seguridad se mantuvo igual. ¿Cómo se debe interpretar esta medida ante la dirección?", ["Como prueba de que el programa de seguridad cumplió por completo sus objetivos de parcheo del año","Como una medida de los resultados de la capacitación de concientización","Como una señal de que existen menos vulnerabilidades","Como un indicador clave de riesgo que muestra una exposición creciente que puede requerir acción"], "Un tiempo de parcheo en aumento indica que la ventana de exposición se amplía, justo lo que un KRI debe alertar a tiempo. Leerlo como menos vulnerabilidades es tentador, pero la métrica no dice nada sobre su cantidad.", ["Un tiempo de parcheo más largo muestra un desempeño que empeora, no metas cumplidas.","Los plazos de parcheo reflejan procesos operativos, no la capacitación de concientización.","La medida sigue cuánto tardan las correcciones, no cuántas vulnerabilidades existen.",null]],
  "x83": ["Un programa de seguridad tiene poco presupuesto y los empleados ignoran sus políticas de forma habitual, diciendo que a la gerencia no le importan. ¿Qué mejoraría más esta situación?", ["El apoyo visible y el patrocinio de la alta dirección","Agregar más controles técnicos en equipos y servidores sin explicárselos al personal","Escribir políticas más largas y detalladas","Contratar una empresa externa de pruebas de penetración"], "El gobierno depende del ejemplo desde arriba; cuando los líderes apoyan la seguridad de forma visible, llegan el presupuesto y el cumplimiento. Más controles técnicos son tentadores como solución rápida, pero no resuelven la falta de compromiso de la dirección.", [null,"Los controles sin explicación suelen generar atajos y no resuelven la falta de apoyo de la dirección.","Políticas más largas no ayudan si el personal ya ignora las que existen.","Una prueba de penetración encuentra debilidades técnicas, pero no cambia el presupuesto ni la cultura."]],
  "x84": ["Un departamento no puede cumplir un nuevo estándar de cifrado durante seis meses porque su sistema heredado no lo admite. ¿Cuál es la mejor respuesta de gobierno?", ["Dejar que el departamento ignore el estándar en silencio hasta que el sistema heredado se reemplace el próximo año","Documentar una excepción formal con controles compensatorios, aprobación del dueño del riesgo y fecha de vencimiento","Reescribir el estándar para que ya no aplique a nadie","Apagar el sistema heredado de inmediato sin importar el impacto en el negocio"], "Una excepción formal y con plazo mantiene visible el riesgo, hace que un dueño responsable lo acepte y agrega controles compensatorios. Ignorar el estándar en silencio es tentador porque evita trámites, pero oculta el riesgo al gobierno.", ["El incumplimiento silencioso deja el riesgo sin seguimiento y sin aprobación de ningún responsable.",null,"Debilitar el estándar para todos quita protección a los sistemas que sí pueden cumplir.","Apagar un sistema de negocio sin evaluar el impacto puede causar más daño que el propio riesgo."]],
  "x85": ["Un desarrollador necesita leer los registros de la aplicación en producción para diagnosticar errores, pero no necesita cambiar nada en los servidores de producción. ¿Qué acceso debe recibir?", ["Derechos completos de administrador en los servidores","El mismo acceso que el líder del equipo de operaciones","Acceso de escritura a la carpeta de la aplicación","Acceso de solo lectura a la ubicación de los registros"], "El mínimo privilegio otorga solo el acceso necesario para la tarea, que aquí es leer registros. Copiar el acceso del líder de equipo es tentador porque es rápido, pero otorga derechos más allá de la necesidad.", ["Los derechos de administrador permiten mucho más que leer registros y violan el mínimo privilegio.","Copiar el acceso más amplio de otra persona otorga derechos que el desarrollador no necesita.","El acceso de escritura a la carpeta de la aplicación permite cambios que la tarea no requiere.",null]],
  "x86": ["La bóveda de un banco solo se puede abrir cuando están presentes dos funcionarios distintos, y cada uno ingresa la mitad de la combinación. ¿Qué control ilustra esto?", ["Rotación de puestos","Vacaciones obligatorias","Control dual con conocimiento dividido","Inicio de sesión único"], "El control dual exige dos personas para completar una acción sensible, y el conocimiento dividido asegura que ninguna tenga el secreto completo. La rotación de puestos es tentadora porque también es un control antifraude, pero actúa con el tiempo y no en el momento del acceso.", ["La rotación de puestos mueve a las personas entre roles con el tiempo; no exige dos personas a la vez.","Las vacaciones obligatorias fuerzan un tiempo fuera para revelar fraudes, no una acción conjunta en una tarea.",null,"El inicio de sesión único permite llegar a muchos sistemas con un inicio de sesión, lo contrario de exigir dos personas."]],
  "x87": ["Una revisión de accesos encuentra una docena de cuentas activas de empleados que dejaron la empresa hace meses. ¿Qué parte del ciclo de vida de la identidad falló?", ["Aprovisionamiento","Desaprovisionamiento","Identificación","Autenticación"], "El desaprovisionamiento quita o desactiva el acceso cuando las personas se van, y las cuentas huérfanas muestran que ese paso se omitió. El aprovisionamiento es tentador porque es el otro extremo del ciclo de vida, pero trata de otorgar acceso.", ["El aprovisionamiento crea el acceso de nuevos usuarios; aquí el problema es un acceso que nunca se quitó.",null,"La identificación es cuando un usuario declara una identidad al iniciar sesión, no la eliminación de cuentas viejas.","La autenticación verifica una identidad declarada; no elimina cuentas cuando las personas se van."]],
  "x88": ["Un banco exige que los empleados en puestos financieros sensibles tomen dos semanas seguidas de descanso cada año mientras otra persona realiza sus tareas. ¿Cuál es el principal propósito de seguridad?", ["Revelar fraudes que el empleado ausente podría estar ocultando","Reducir el costo de las horas extra de los empleados","Dar tiempo al equipo de TI para parchar sus estaciones de trabajo","Aplicar el mínimo privilegio en sus cuentas"], "Las vacaciones obligatorias ponen a otra persona en el puesto, lo que puede exponer un fraude en curso que requiere la atención constante del empleado original. El mínimo privilegio es tentador porque también es un principio de acceso, pero no depende de la ausencia.", [null,"El ahorro de costos no es el objetivo de seguridad de este control.","Los parches se pueden aplicar sin que el empleado esté fuera dos semanas.","El mínimo privilegio limita los derechos de acceso; no se logra haciendo que alguien tome licencia."]],
  "x89": ["Una empresa quiere que los administradores no tengan derechos de administrador permanentes. En cambio, piden elevación para una tarea aprobada, la reciben por un período limitado y la pierden automáticamente después. ¿Cómo se llama este enfoque?", ["Acceso privilegiado justo a tiempo","Control de acceso discrecional","Control de acceso basado en roles","Inicio de sesión único"], "El acceso justo a tiempo, una práctica central de la gestión de accesos privilegiados, otorga derechos elevados solo cuando hacen falta y los quita automáticamente. El RBAC es tentador porque los administradores sí tienen roles, pero los permisos por rol son permanentes, no temporales.", [null,"El DAC permite que los dueños de los recursos otorguen acceso a su criterio, sin elevación por tiempo limitado.","El RBAC asigna permisos por rol, pero esos permisos suelen quedar fijos de forma permanente.","El SSO reduce la cantidad de inicios de sesión; no otorga ni quita derechos de administrador con el tiempo."]],
  "x90": ["Una empresa tiene una cuenta de administrador de emergencia cuya contraseña está sellada en una caja fuerte y que solo se usa si fallan los sistemas normales de inicio de sesión. ¿Qué práctica gestiona mejor el riesgo de esta cuenta?", ["Compartir la contraseña por correo con todos los administradores para tenerla siempre a mano durante una caída","Desactivar el registro de la cuenta para evitar exceso de alertas","Usarla a diario para que los administradores se familiaricen con ella","Alertar ante cualquier uso, cambiar la contraseña después de cada uso y revisar cada sesión"], "Una cuenta de emergencia es muy poderosa, así que cada uso debe generar alertas, revisarse y seguirse de un cambio de contraseña. Usarla a diario es tentador para asegurarse de que funcione, pero anula el propósito de una cuenta solo para emergencias.", ["Compartir la contraseña con muchos elimina el control y la rendición de cuentas sobre una cuenta muy privilegiada.","Desactivar el registro oculta justamente el uso que más necesita revisarse.","El uso diario convierte una cuenta de emergencia en una cuenta privilegiada permanente y aumenta el riesgo.",null]],
  "x91": ["Una empresa implementa inicio de sesión único para que los empleados usen un solo acceso para el correo, RR. HH. y las aplicaciones financieras. ¿Qué riesgo aumenta con esto y qué control lo compensa mejor?", ["Los usuarios deben recordar más contraseñas, así que deben anotarlas","Cada aplicación ya no puede registrar quién accedió, así que hay que desactivar el SSO para poder auditar","Una credencial robada puede abrir muchas aplicaciones, así que se debe exigir MFA en el proveedor de identidad","El cifrado deja de funcionar, así que hay que pasar las aplicaciones a HTTP sin cifrar"], "Con SSO, una credencial comprometida puede llegar a todas las aplicaciones conectadas, así que una MFA sólida en el proveedor de identidad es esencial. Decir que los usuarios deben recordar más contraseñas es tentador, pero el SSO hace lo contrario.", ["El SSO reduce la cantidad de contraseñas que los usuarios deben recordar, no la aumenta.","Con SSO, las aplicaciones y el proveedor de identidad pueden seguir registrando los accesos.",null,"El SSO no rompe el cifrado, y pasar a HTTP sin cifrar debilitaría la seguridad."]],
  "x92": ["¿Qué control de seguridad física puede usar el criterio humano para interrogar a un visitante, reaccionar ante una situación inesperada y pedir ayuda?", ["Una cámara de CCTV","Un guardia de seguridad","Un lector de credenciales","Una cerca perimetral"], "Los guardias son el control físico que puede aplicar criterio y reaccionar ante situaciones cambiantes. El CCTV es tentador porque vigila el área, pero solo graba; una persona igual debe actuar según lo que muestra.", ["Una cámara graba o muestra la actividad, pero no puede interrogar a nadie ni decidir cómo reaccionar.",null,"Un lector de credenciales sigue reglas fijas y no puede evaluar situaciones inusuales.","Una cerca es una barrera pasiva que no puede reaccionar ante los eventos."]],
  "x93": ["Una empresa exige que cada visitante firme un registro, use una credencial de visitante visible y esté acompañado por un empleado en todo momento dentro de la oficina. ¿Cuál es el principal propósito de estas medidas?", ["Cifrar los datos de los visitantes","Agilizar el ingreso de los visitantes","Controlar y registrar el acceso de los visitantes a las instalaciones","Reemplazar la necesidad de cerraduras en las puertas"], "Los registros, credenciales y acompañantes limitan a dónde pueden ir los visitantes y dejan constancia de quién estuvo presente. Reemplazar las cerraduras es tentador si se ve al acompañante como una barrera, pero estas medidas se suman a las cerraduras en lugar de sustituirlas.", ["Son medidas de acceso físico y no tienen relación con cifrar datos.","Los requisitos de registro y acompañamiento agregan pasos en lugar de agilizar el ingreso.",null,"Los procedimientos para visitantes funcionan junto con las cerraduras; no las reemplazan."]],
  "x94": ["En un sistema de control de acceso discrecional (DAC), un usuario ejecuta un programa malicioso que comparte en silencio sus archivos con alguien externo. ¿Por qué el DAC está especialmente expuesto a esto?", ["Los programas se ejecutan con los derechos del usuario, y el usuario, como dueño, puede dar acceso a cualquiera","Los sistemas DAC no pueden autenticar usuarios","El DAC exige que todos los archivos sean públicos","El DAC depende de etiquetas de clasificación y habilitaciones asignadas por el sistema que el malware puede cambiar fácilmente"], "En el DAC, los dueños controlan los permisos, así que un malware que actúa con los derechos del dueño puede cambiarlos y compartir datos libremente. La respuesta de las etiquetas es tentadora, pero las etiquetas son propias del MAC, donde los usuarios no pueden cambiar permisos a voluntad.", [null,"Los sistemas DAC sí autentican usuarios; la debilidad está en cómo los dueños otorgan acceso.","En el DAC los archivos no son públicos por defecto; los dueños deciden quién accede.","Las etiquetas de clasificación son propias del control de acceso obligatorio, no del DAC."]],
  "x95": ["Un sistema bloquea una cuenta durante 15 minutos después de cinco intentos fallidos seguidos de inicio de sesión. ¿Qué amenaza busca frenar principalmente este control?", ["Tailgating para entrar al edificio","Escucha del tráfico de red","Robo de cintas de respaldo","Adivinación de contraseñas y ataques de fuerza bruta"], "El bloqueo de cuentas limita cuántos intentos puede hacer un atacante, lo que frena la fuerza bruta y la adivinación de contraseñas. La escucha es tentadora porque también es una forma de obtener contraseñas, pero el bloqueo no impide que se capture el tráfico.", ["El tailgating es una amenaza de ingreso físico que el bloqueo de cuentas no puede afectar.","La escucha captura tráfico en tránsito y no se detiene limitando los intentos de inicio de sesión.","El robo de respaldos es un riesgo de medios físicos sin relación con los intentos de inicio de sesión.",null]],
  "x96": ["Durante una revisión trimestral de accesos, ¿quién suele estar en mejor posición para confirmar si cada empleado todavía necesita acceso a una aplicación financiera sensible?", ["El técnico de mesa de ayuda que creó originalmente las cuentas en el directorio","El gerente del empleado o el dueño de los datos de la aplicación","El propio empleado","Un evaluador externo de pruebas de penetración"], "Los gerentes y los dueños de los datos entienden la necesidad del negocio, así que son las personas indicadas para certificar el acceso. La mesa de ayuda es tentadora porque administra las cuentas, pero no decide quién las necesita.", ["La mesa de ayuda crea cuentas a pedido, pero no conoce la necesidad de negocio actual de cada persona.",null,"Los empleados tienen un conflicto de interés al aprobar su propio acceso.","Un evaluador de penetración busca debilidades técnicas, no si el acceso de una persona está justificado."]],
  "x97": ["Un administrador necesita permitir el acceso seguro remoto por línea de comandos a servidores Linux a través del firewall. ¿Qué puerto debe abrir?", ["23","22","25","80"], "SSH usa el puerto TCP 22 y ofrece sesiones remotas cifradas por línea de comandos. El puerto 23 es tentador porque Telnet también ofrece línea de comandos remota, pero no está cifrado.", ["El puerto 23 es Telnet, que envía todo, incluidas las contraseñas, en texto claro.",null,"El puerto 25 es SMTP para mover correo entre servidores, no para la administración remota.","El puerto 80 es tráfico web HTTP sin cifrar, no acceso por línea de comandos."]],
  "x98": ["Un switch de red reenvía tramas al puerto correcto leyendo sus direcciones MAC. ¿En qué capa del modelo OSI ocurre esto?", ["Capa 3, red","Capa 4, transporte","Capa 1, física","Capa 2, enlace de datos"], "Las direcciones MAC y las tramas pertenecen a la capa de enlace de datos, donde operan los switches. La capa 3 es tentadora porque también trata con direcciones, pero usa direcciones IP y routers.", ["La capa 3 enruta paquetes usando direcciones IP, no direcciones MAC.","La capa 4 maneja puertos y la entrega de extremo a extremo con TCP o UDP.","La capa 1 transmite bits por el medio y no lee direcciones.",null]],
  "x99": ["¿Cuál de las siguientes direcciones IPv4 es privada y no se enruta en internet pública?", ["192.168.10.25","8.8.8.8","172.32.1.1","11.0.0.5"], "192.168.0.0/16 es uno de los rangos privados, junto con 10.0.0.0/8 y 172.16.0.0/12. 172.32.1.1 es tentadora porque se parece al bloque privado 172.16, pero ese bloque termina en 172.31.", [null,"8.8.8.8 es una dirección pública muy conocida que se usa en internet.","172.32.1.1 queda justo fuera del rango privado 172.16.0.0 a 172.31.255.255.","11.0.0.5 está fuera del rango privado 10.0.0.0/8 y se puede enrutar públicamente."]],
  "x100": ["Unos investigadores recuperan la clave de cifrado de un dispositivo midiendo con cuidado pequeños cambios en su consumo de energía mientras realiza operaciones criptográficas. ¿Qué tipo de ataque es este?", ["Ataque de phishing","Ataque de denegación de servicio","Ataque de canal lateral","Inyección SQL"], "Los ataques de canal lateral obtienen secretos a partir de efectos físicos como el consumo de energía, los tiempos o las emisiones, en lugar de fallas del algoritmo. La denegación de servicio es tentadora porque también ataca dispositivos, pero interrumpe el servicio en lugar de extraer datos.", ["El phishing engaña a las personas para que revelen información; no mide el consumo de energía de un dispositivo.","Un ataque de denegación de servicio busca dejar un sistema no disponible, no extraer claves.",null,"La inyección SQL ataca bases de datos de aplicaciones con entradas manipuladas, no señales del hardware."]],
  "x101": ["Un malware se propaga por sí solo de una computadora a otra por la red, explotando una vulnerabilidad sin que ningún usuario abra un archivo ni haga clic en un enlace. ¿Qué tipo de malware es este?", ["Troyano","Virus de macro","Adware","Gusano"], "Los gusanos se propagan solos por la red sin acción del usuario, a menudo explotando vulnerabilidades. El troyano es tentador porque también es un malware común, pero depende de engañar a un usuario para que lo ejecute.", ["Un troyano se disfraza de software legítimo y depende de que un usuario lo ejecute.","Un virus de macro necesita que un usuario abra un documento infectado para ejecutarse.","El adware muestra anuncios no deseados y normalmente no se propaga solo por la red.",null]],
  "x102": ["Una variante de malware completamente nueva todavía no tiene firma conocida, pero empieza a cifrar muchos archivos rápidamente en una laptop. ¿Qué capacidad antimalware tiene más probabilidades de detectarla?", ["Detección basada en firmas","Detección basada en comportamiento (heurística)","Un filtro de paquetes sin estado","Cifrado de disco completo"], "La detección basada en comportamiento marca acciones sospechosas, como el cifrado masivo de archivos, aunque no exista una firma. La detección por firmas es tentadora porque es el método clásico del antivirus, pero solo reconoce malware conocido.", ["La detección por firmas necesita un patrón conocido, y esta variante nueva todavía no lo tiene.",null,"Un filtro de paquetes sin estado revisa encabezados de red y no ve la actividad de archivos en la laptop.","El cifrado de disco completo protege los datos si se pierde el equipo, pero no detecta malware."]],
  "x103": ["Un ataque real pasó por la red y comprometió un servidor, pero el sistema de detección de intrusiones no generó ninguna alerta. ¿Cómo se llama este resultado?", ["Un falso positivo","Un verdadero positivo","Un falso negativo","Un verdadero negativo"], "Un falso negativo ocurre cuando un ataque real pasa sin detectarse, la falla de detección más peligrosa. El falso positivo es tentador porque también es un error, pero significa una alerta ante actividad inofensiva.", ["Un falso positivo es una alerta por una actividad que en realidad era inofensiva.","Un verdadero positivo es una alerta correcta ante actividad maliciosa real, y aquí no hubo alerta.",null,"Un verdadero negativo es no alertar correctamente cuando no hubo ataque."]],
  "x104": ["El tráfico hacia un servidor web está cifrado de extremo a extremo con TLS, así que un sensor de red en el segmento no puede ver el contenido de las solicitudes. ¿Qué tipo de detección de intrusiones está en mejor posición para inspeccionar la actividad ya descifrada?", ["Un IDS basado en host en el servidor web","Un IDS basado en red en el puerto espejo del switch","Un filtro de paquetes sin estado en el borde","Un honeypot en otra parte de la red"], "Un IDS basado en host se ejecuta en el servidor, donde el tráfico ya está descifrado, así que puede ver las solicitudes reales y la actividad del sistema. El IDS basado en red es tentador porque es el sensor de tráfico habitual, pero no puede leer contenido cifrado.", [null,"Un sensor de red solo ve tráfico cifrado, que es justamente la limitación de este escenario.","Un filtro sin estado revisa direcciones y puertos y no puede inspeccionar el contenido descifrado.","Un honeypot atrae a los atacantes hacia un señuelo; no inspecciona el tráfico hacia el servidor real."]],
  "x105": ["Un firewall permite automáticamente las respuestas a una solicitud web que inició un usuario interno, sin una regla de entrada separada, porque sigue cada conexión. ¿Qué tipo de firewall es este?", ["Firewall con estado","Filtro de paquetes sin estado","Solo un proxy de caché","Hub de red"], "Un firewall con estado mantiene una tabla de conexiones activas y permite automáticamente el tráfico de retorno que coincide. El filtro sin estado es tentador porque también usa reglas, pero no recuerda las conexiones.", [null,"Un filtro sin estado juzga cada paquete por separado, así que las respuestas necesitan sus propias reglas.","Un proxy de caché guarda contenido web; lo que define este comportamiento es el seguimiento de conexiones.","Un hub solo repite el tráfico a todos los puertos y no filtra nada."]],
  "x106": ["Un desarrollador crea un servidor virtual nuevo desde el portal web del proveedor de nube en pocos minutos, sin llamar ni escribir a nadie del proveedor. ¿Qué característica de la nube muestra esto?", ["Servicio medido","Agrupación de recursos","Autoservicio bajo demanda","Implementación comunitaria"], "El autoservicio bajo demanda permite que los clientes aprovisionen recursos por sí mismos cuando los necesitan. El servicio medido es tentador porque es otra característica central de la nube, pero trata de cómo se mide y factura el uso.", ["El servicio medido trata de medir y facturar el uso, no de aprovisionar sin ayuda.","La agrupación de recursos es que el proveedor comparta hardware entre clientes, no el autoaprovisionamiento.",null,"La comunitaria es un modelo de implementación para grupos con necesidades comunes, no una característica del servicio."]],
  "x107": ["Según el modelo de responsabilidad compartida, ¿qué tarea sigue siendo responsabilidad del proveedor de nube tanto en IaaS como en PaaS y SaaS?", ["Administrar qué usuarios pueden acceder a los datos del cliente","La seguridad física de los centros de datos","Clasificar los datos del cliente","Configurar las contraseñas de los usuarios del cliente"], "El proveedor siempre protege las instalaciones físicas, mientras que el cliente siempre conserva la responsabilidad sobre sus datos y el acceso de sus usuarios. Administrar el acceso de usuarios es tentador porque el proveedor ofrece las herramientas, pero usarlas bien es tarea del cliente.", ["Decidir quién accede a los datos del cliente sigue siendo responsabilidad del cliente en todos los modelos.",null,"Clasificar los datos siempre es tarea del cliente, porque solo él conoce su valor.","Los clientes administran las credenciales y las prácticas de contraseñas de sus propios usuarios."]],
  "x108": ["La tabla de conexiones de un servidor web se llena con miles de conexiones TCP semiabiertas desde direcciones falsificadas que nunca completan el handshake, y los usuarios legítimos no pueden conectarse. ¿Qué ataque es este?", ["Ataque de intermediario (on-path)","Ataque de canal lateral","Rociado de contraseñas","Inundación SYN"], "Una inundación SYN envía solicitudes de conexión sin completar el handshake, agota la capacidad del servidor y deniega el servicio. El ataque de intermediario es tentador porque también usa falsificación, pero su objetivo es interceptar, no agotar recursos.", ["Un atacante intermediario retransmite y lee el tráfico entre las partes, no agota tablas de conexiones.","Un ataque de canal lateral extrae secretos de efectos físicos, no inundando conexiones.","El rociado de contraseñas prueba contraseñas comunes en muchas cuentas; no crea conexiones semiabiertas.",null]],
  "x109": ["En la LAN de una oficina, un atacante envía respuestas ARP falsificadas que afirman que la dirección IP del gateway predeterminado pertenece a la dirección MAC del atacante. ¿Qué intenta lograr más probablemente el atacante?", ["Cifrar los archivos de las víctimas para pedir un rescate","Ubicarse en la ruta para interceptar el tráfico que va hacia el gateway","Adivinar las contraseñas de los usuarios por fuerza bruta","Agotar el pool de direcciones del servidor DHCP para que los nuevos equipos de la LAN no puedan conectarse"], "El envenenamiento ARP hace que las víctimas envíen el tráfico del gateway al atacante, que queda en la ruta para leerlo o alterarlo. El agotamiento de DHCP es tentador porque es otro ataque de LAN, pero funciona pidiendo concesiones, no falsificando ARP.", ["El ransomware cifra archivos en los equipos; las respuestas ARP falsas, en cambio, redirigen el tráfico de red.",null,"La fuerza bruta prueba contraseñas una y otra vez y no tiene relación con las respuestas ARP.","Agotar DHCP requiere muchas solicitudes de direcciones, no respuestas ARP falsas sobre el gateway."]],
  "x110": ["Un equipo de desarrollo está diseñando cómo guardará una nueva aplicación las contraseñas de los usuarios en su base de datos. ¿Cuál es la mejor práctica?", ["Guardar un hash con sal generado por un algoritmo lento de hash de contraseñas","Guardar las contraseñas cifradas con una sola clave simétrica robusta almacenada en el servidor de la aplicación","Guardar las contraseñas en texto plano en una tabla restringida","Guardar las contraseñas codificadas en Base64"], "Los hashes lentos con sal son de un solo sentido y encarecen el descifrado de hashes robados, mientras la sal anula las tablas precalculadas. El cifrado es tentador porque protege datos, pero es reversible, así que una clave robada expone todas las contraseñas.", [null,"Las contraseñas cifradas se pueden descifrar todas si se roba la única clave.","El texto plano expone de inmediato todas las contraseñas si alguien lee la tabla.","Base64 es una codificación, no una protección, y se revierte con facilidad."]],
  "x111": ["Alicia quiere que Bruno pueda verificar que un contrato realmente proviene de ella y no fue alterado. ¿Qué clave usa Alicia para crear la firma digital?", ["La clave pública de Alicia","La clave pública de Bruno","La clave privada de Bruno","La clave privada de Alicia"], "Una firma se crea con la clave privada del remitente y se verifica con su clave pública, lo que prueba el origen y la integridad. La clave pública de Bruno es tentadora porque se usa para enviarle mensajes confidenciales, pero eso da secreto, no una firma.", ["La clave pública de Alicia es la que Bruno usa para verificar la firma, no para crearla.","Cifrar con la clave pública de Bruno da confidencialidad para Bruno, no prueba que Alicia lo envió.","Alicia nunca tiene la clave privada de Bruno, y usarla no probaría nada sobre Alicia.",null]],
  "x112": ["Según el esquema de clasificación de datos de una empresa, ¿en qué categoría estaría normalmente un comunicado de prensa aprobado que ya está publicado en el sitio web de la empresa?", ["Confidencial","Restringido","Público","Solo uso interno"], "La información aprobada para darse a conocer a cualquiera se clasifica como pública y necesita poca protección contra la divulgación. Solo uso interno es tentador porque el comunicado salió de la empresa, pero ya está publicado.", ["Los datos confidenciales causarían daño si se divulgan, pero este comunicado es para todos.","Restringido es el nivel más sensible, para datos que necesitan la protección más fuerte.",null,"Los datos de solo uso interno son para los empleados, pero este comunicado ya se publicó."]],
  "x113": ["Un atacante que obtiene derechos de administrador en un servidor podría borrar los registros locales para ocultar sus huellas. ¿Cuál es la mejor forma de proteger la evidencia de los registros?", ["Guardar los registros solo en el disco local del servidor","Desactivar el registro para ahorrar espacio","Reenviar los registros en tiempo real a un servidor central de registros o SIEM que los administradores del servidor no puedan modificar","Imprimir los registros una vez al mes"], "Enviar los registros fuera del equipo en tiempo real conserva una copia protegida aunque el servidor se comprometa. Guardarlos localmente es tentador porque es lo predeterminado, pero los administradores locales, incluido un atacante, pueden borrarlos.", ["Los registros locales son justamente lo que un atacante con derechos de administrador puede borrar.","Desactivar el registro elimina la evidencia por completo en lugar de protegerla.",null,"Imprimir una vez al mes deja semanas de actividad sin protección y es difícil de buscar."]],
  "x114": ["Se acaba de publicar un parche crítico del sistema operativo. Antes de desplegarlo en todos los servidores de producción, ¿qué debe ocurrir normalmente primero?", ["Desplegarlo en todos los servidores a la vez para ahorrar tiempo","Esperar un año para ver si otras empresas tienen problemas","Desinstalar el antivirus para evitar conflictos","Probar el parche en un entorno que no sea de producción"], "Probar los parches primero detecta problemas de compatibilidad antes de que lleguen a producción, como parte de la gestión de parches y cambios. Desplegarlo en todos lados a la vez es tentador porque el parche es crítico, pero un parche sin probar puede causar su propia caída.", ["Desplegarlo en todos lados a la vez arriesga una caída general si el parche causa problemas.","Esperar un año deja abierta una vulnerabilidad crítica durante demasiado tiempo.","Quitar el antivirus debilita la protección y no forma parte de las pruebas normales de parches.",null]],
  "x115": ["Una herramienta compara la configuración de seguridad actual de cada servidor con una configuración segura aprobada e informa cualquier servidor que se haya desviado. ¿Qué práctica apoya esto?", ["Gestión de la configuración frente a una línea base","Análisis de impacto en el negocio","Clasificación de datos","Prueba de penetración"], "La gestión de la configuración mantiene los sistemas alineados con una línea base aprobada y marca las desviaciones no autorizadas. La prueba de penetración es tentadora porque también encuentra debilidades, pero simula ataques en lugar de comparar configuraciones.", [null,"Un BIA ordena las funciones del negocio según su impacto, no la configuración de los servidores.","La clasificación de datos etiqueta la información según su sensibilidad, no la configuración de los sistemas.","La prueba de penetración intenta explotar debilidades en lugar de comparar configuraciones con un estándar."]],
  "x116": ["Con autorización por escrito, un equipo intenta explotar activamente las debilidades de una aplicación web de la empresa para mostrar lo que podría lograr un atacante real. ¿Qué actividad es esta?", ["Escaneo de vulnerabilidades","Prueba de penetración","Revisión de registros","Análisis de impacto en el negocio"], "La prueba de penetración va más allá de encontrar debilidades: las explota de forma segura para demostrar el impacto real. El escaneo de vulnerabilidades es tentador porque también busca debilidades, pero se queda en identificarlas.", ["Un escaneo de vulnerabilidades identifica posibles debilidades, pero no intenta explotarlas.",null,"La revisión de registros examina actividad pasada en lugar de probar las defensas.","Un BIA evalúa el impacto de perder funciones del negocio, no debilidades técnicas."]],
  "x117": ["Un analista confirma que una alerta refleja un compromiso real y trabaja para determinar qué sistemas y cuentas están afectados. ¿Qué fase de la respuesta a incidentes es esta?", ["Preparación","Erradicación","Lecciones aprendidas","Detección y análisis"], "Confirmar un incidente y delimitar su impacto pertenece a la detección y el análisis. La erradicación es tentadora porque el analista trabaja sobre el compromiso, pero la eliminación ocurre solo después de delimitar y contener.", ["La preparación ocurre antes de los incidentes, creando planes, herramientas y capacitación.","La erradicación elimina la amenaza después de entender su alcance y contenerla.","Las lecciones aprendidas son la revisión que se hace después de resolver el incidente.",null]],
  "x118": ["Una empresa hace un respaldo completo cada domingo y un respaldo diferencial las demás noches. Un servidor falla el jueves por la mañana. ¿Qué respaldos se necesitan para restaurar los datos más recientes?", ["El respaldo completo del domingo y todos los diferenciales de lunes a miércoles","Solo el diferencial del miércoles por la noche","El respaldo completo del domingo y el diferencial del miércoles por la noche","Solo el respaldo completo del domingo"], "Un diferencial contiene todos los cambios desde el último respaldo completo, así que el completo más el diferencial más reciente restauran los datos más actuales. Restaurar todos los diferenciales es tentador, pero así funcionan los respaldos incrementales, no los diferenciales.", ["Cada diferencial ya incluye todos los cambios desde el domingo, así que los anteriores no hacen falta.","Un diferencial solo contiene los cambios desde el respaldo completo, así que no se puede restaurar por sí solo.",null,"El respaldo completo por sí solo perdería todos los cambios de lunes a miércoles."]],
  "x119": ["A una empresa le preocupa que un ransomware cifre sus respaldos junto con los datos de producción. ¿Qué práctica de respaldo protege mejor contra esto?", ["Guardar todos los respaldos en un recurso compartido asignado a todas las PC de los usuarios","Mantener al menos una copia de respaldo fuera de línea o inmutable","Respaldar solo una vez al año para reducir la exposición","Guardar los respaldos en el mismo servidor que los datos"], "Una copia fuera de línea o inmutable no puede ser modificada por un ransomware que se ejecuta en la red, así que sigue disponible para recuperar. Guardar los respaldos en el mismo servidor es tentador por comodidad, pero corre la misma suerte que los datos.", ["Un recurso compartido asignado a todas las PC es justamente donde el ransomware puede llegar y cifrar los respaldos.",null,"Respaldar una vez al año perdería hasta un año de datos y no evita el cifrado de los respaldos.","Los respaldos en el mismo servidor caen con él cuando el ransomware cifra ese servidor."]],
  "x120": ["Los empleados nuevos deben leer y firmar un documento que describe lo que pueden y no pueden hacer con las computadoras, el correo y el acceso a internet de la empresa. ¿Qué documento es este?", ["Política de uso aceptable (AUP)","Plan de continuidad del negocio","Acuerdo de nivel de servicio","Plan de recuperación ante desastres"], "Una AUP define el uso aceptable y prohibido de los recursos de la empresa, y los empleados la aceptan al firmarla. El SLA es tentador porque también es un acuerdo firmado, pero trata de niveles de servicio y no del comportamiento de los usuarios.", [null,"Un plan de continuidad del negocio explica cómo seguir operando durante una interrupción, no la conducta de los usuarios.","Un SLA fija compromisos de servicio entre un proveedor y un cliente, no el comportamiento de los empleados.","Un plan de recuperación ante desastres cubre la restauración de TI después de un desastre, no el uso diario de los sistemas."]]
});
